-- Vorrats-Aufgaben (rollend-14) in bestehende Flüge einfügen: 213 Aufgaben, 14 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (10, 'bruch.dezimal', 591, 24, $auf$[{"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Dezimalzahl hat 4 Einer, 0 Zehntel, 7 Hundertstel und 5 Tausendstel. Wie viele Tausendstel sind das insgesamt?"}, "o": {"wert": 4075}, "h": "Wie viele Tausendstel sind 1 Einer? Wie viele Tausendstel sind 1 Hundertstel?", "w": "1 Einer sind 1 000 Tausendstel, also 4 Einer sind 4 000 Tausendstel. 1 Hundertstel sind 10 Tausendstel, also 7 Hundertstel sind 70. Dazu 5 Tausendstel: 4 000 + 70 + 5 = 4 075.", "form": "anwenden", "zaehlt": "ja", "r": 14592}, {"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Beim Weitsprung springt Sam 4,58 m. Kim springt 4,5 m. Um wie viele Zentimeter ist Sams Sprung weiter?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Rechne beide Weiten in Zentimeter um. 1 m sind 100 cm.", "w": "4,58 m = 458 cm und 4,5 m = 450 cm. Der Unterschied ist 458 − 450 = 8 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14593}, {"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Aus den Ziffern 2, 5 und 8 wird eine Dezimalzahl gebildet. Jede Ziffer wird genau einmal benutzt, das Komma steht nach der ersten Ziffer. Um wie viele Hundertstel ist die größte solche Zahl größer als die kleinste?"}, "o": {"wert": 594, "einheit": "Hundertstel"}, "h": "Welche Ziffer muss vorne stehen, damit die Zahl möglichst groß oder möglichst klein ist? Dann ordnest du die restlichen Ziffern.", "w": "Größte Zahl: 8,52. Kleinste Zahl: 2,58. Unterschied: 8,52 − 2,58 = 5,94. Das sind 594 Hundertstel.", "form": "anwenden", "zaehlt": "ja", "r": 14594}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Vier Schnecken kriechen in einer Stunde 0,36 m, 0,6 m, 0,306 m und 0,63 m weit. Um wie viele Millimeter ist die schnellste Schnecke weiter gekommen als die langsamste?"}, "o": {"wert": 324, "einheit": "mm"}, "h": "Welche Schnecke ist am weitesten gekommen, welche am wenigsten weit? Fülle mit Endnullen auf: 0,630 und 0,306.", "w": "Am weitesten: 0,63 m = 630 mm. Am wenigsten: 0,306 m = 306 mm. Unterschied: 630 − 306 = 324 mm.", "form": "anwenden", "zaehlt": "ja", "r": 14595}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Für wie viele Ziffern □ liegt die Zahl 3,4□ zwischen 3,42 und 3,48? Die Zahlen 3,42 und 3,48 selbst zählen nicht mit."}, "o": {"wert": 5}, "h": "Welche Ziffern □ machen 3,4□ größer als 3,42? Welche machen es kleiner als 3,48?", "w": "Größer als 3,42 ist 3,4□ ab □ = 3. Kleiner als 3,48 ist es bis □ = 7. Möglich sind 3, 4, 5, 6 und 7: das sind 5 Ziffern.", "form": "anwenden", "zaehlt": "ja", "r": 14596}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Zahl hat genau zwei Nachkommastellen und liegt zwischen 3,7 und 3,8. Die Quersumme aller ihrer Ziffern ist 18. Welche Zahl ist es?"}, "o": {"wert": 3.78}, "h": "Die Zahl sieht so aus: 3,7 und eine letzte Ziffer. Welche Ziffer fehlt, damit die Quersumme 18 ist?", "w": "Die Zahl hat die Form 3,7x. Die Quersumme ist 3 + 7 + x = 18, also x = 8. Die Zahl ist 3,78. Sie liegt zwischen 3,70 und 3,80.", "form": "anwenden", "zaehlt": "ja", "r": 14597}, {"l": "runden", "t": "runden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Wasserzähler zeigt 0,3846 m³. Runde auf Hundertstel. Wie viele Kubikmeter sind das gerundet?"}, "o": {"wert": 0.38, "einheit": "m³"}, "h": "Die Rundungsstelle ist die zweite Stelle nach dem Komma. Schau auf die Ziffer direkt rechts davon.", "w": "Hundertstel: 0,38. Die Ziffer rechts davon ist 4, also wird abgerundet. Ergebnis: 0,38 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14598}, {"l": "runden", "t": "runden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Alex tauscht 85 € in Schweizer Franken. Für 1 € bekommt man 0,9432 Franken. Wie viele Franken sind das, auf Rappen genau (zwei Nachkommastellen) gerundet?"}, "o": {"wert": 80.17, "einheit": "Franken"}, "h": "Rechne zuerst den genauen Betrag aus. Dann rundest du auf Hundertstel.", "w": "85 · 0,9432 = 80,172. Auf Hundertstel gerundet: Die Ziffer rechts ist 2, also abrunden. Ergebnis: 80,17 Franken.", "form": "anwenden", "zaehlt": "ja", "r": 14599}, {"l": "runden", "t": "runden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Auf einem Display steht eine Zahl mit genau zwei Nachkommastellen, zum Beispiel 6,00. Sie wird auf eine ganze Zahl gerundet: Hat die Zehntelziffer den Wert 5 oder mehr, wird aufgerundet. Das Ergebnis ist 6. Wie viele verschiedene Anzeigen kann es gewesen sein?"}, "o": {"wert": 100}, "h": "Welche ist die kleinste, welche die größte Zahl, die auf 6 gerundet wird? Zähle die Hundertstel von der kleinsten bis zur größten.", "w": "Ab 5,50 (Zehntelziffer 5) wird auf 6 aufgerundet, bis 6,49 (Zehntelziffer 4) wird auf 6 abgerundet. Die Zahlen sind 5,50 bis 6,49, also 550 bis 649 Hundertstel. Das sind 649 − 550 + 1 = 100 Zahlen.", "form": "anwenden", "zaehlt": "ja", "r": 14600}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim hat 9/25 des Schulwegs mit dem Rad geschafft. Schreibe den Anteil als Dezimalzahl."}, "o": {"wert": 0.36}, "h": "Erweitere 9/25 auf den Nenner 100. Mit welcher Zahl musst du 25 malnehmen?", "w": "Erweitern mit 4: 9/25 = 36/100 = 0,36. Probe: 9 : 25 = 0,36.", "form": "anwenden", "zaehlt": "ja", "r": 14601}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Stab ist 7/20 m lang. Wie viele Zentimeter sind das?"}, "o": {"wert": 35, "einheit": "cm"}, "h": "Erweitere 7/20 auf den Nenner 100. Dann siehst du die Hundertstel.", "w": "7/20 = 35/100 = 0,35 m. Das sind 0,35 · 100 = 35 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14602}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Dezimalzahl d hat denselben Wert wie 13/20. Wie groß ist d + 1/8 + 3/16? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 0.9625}, "h": "Schreibe jeden Bruch als Dezimalzahl. Erweitere 1/8 auf Tausendstel und 3/16 auf Zehntausendstel.", "w": "13/20 = 65/100 = 0,65. 1/8 = 125/1000 = 0,125. 3/16 = 1875/10000 = 0,1875. Summe: 0,65 + 0,125 + 0,1875 = 0,9625.", "form": "anwenden", "zaehlt": "ja", "r": 14603}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schnur ist 0,35 m lang. Schreibe 0,35 als vollständig gekürzten Bruch. Welche Zahl steht im Zähler?"}, "o": {"wert": 7}, "h": "0,35 sind 35/100. Kürze mit der größten Zahl, die in 35 und in 100 steckt.", "w": "0,35 = 35/100. Der größte gemeinsame Teiler ist 5. Gekürzt: 7/20. Im Zähler steht 7.", "form": "anwenden", "zaehlt": "ja", "r": 14604}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rezept braucht 0,625 kg Mehl. Wie viele Achtel Kilogramm sind das?"}, "o": {"wert": 5}, "h": "0,625 sind 625/1 000. Kürze mit 125. Welchen Nenner erhältst du?", "w": "0,625 = 625/1000 = 5/8. Das sind 5 Achtel Kilogramm. Probe: 5 · 0,125 = 0,625.", "form": "anwenden", "zaehlt": "ja", "r": 14605}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Kim schreibt: „0,075 = 75/100 = 3/4.“ Kims Kürzung ist richtig, trotzdem stimmt das Ergebnis nicht. Welchen Nenner hat der richtige, vollständig gekürzte Bruch?"}, "o": {"wert": 40}, "h": "Wie viele Nachkommastellen hat 0,075? Danach richtet sich der Nenner, bevor du kürzt.", "w": "Kims Kürzung 75/100 = 3/4 ist richtig. Falsch ist der Nenner 100: 0,075 hat 3 Nachkommastellen, also 75/1000. Kürzen mit 25 ergibt 3/40. Der Nenner ist 40.", "form": "anwenden", "zaehlt": "ja", "r": 14606}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Messbecher ist mit 1/8 Liter gefüllt. Wie viele Milliliter sind das?"}, "o": {"wert": 125, "einheit": "ml"}, "h": "Du weißt: 1/8 = 0,125. Ein Liter hat 1 000 ml.", "w": "1/8 l = 0,125 l. Das sind 0,125 · 1 000 = 125 ml.", "form": "anwenden", "zaehlt": "ja", "r": 14607}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Sam hat 3/5 eines Buches mit 250 Seiten gelesen. Wie viele Seiten fehlen noch?"}, "o": {"wert": 100}, "h": "Du weißt: 1/5 = 0,2. Wie viele Seiten hat Sam gelesen? Dann ziehst du ab.", "w": "3/5 = 0,6. Gelesen: 0,6 · 250 = 150 Seiten. Es fehlen 250 − 150 = 100 Seiten.", "form": "anwenden", "zaehlt": "ja", "r": 14608}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Wie viel Prozent sind 1/4 + 0,125 + 3/5 zusammen?"}, "o": {"wert": 97.5, "einheit": "%"}, "h": "Schreibe jeden Summanden als Dezimalzahl: 1/4 = 0,25 und 3/5 = 0,6. Addiere. Dann rechnest du in Prozent um.", "w": "0,25 + 0,125 + 0,6 = 0,975. In Prozent: 0,975 · 100 = 97,5 %.", "form": "anwenden", "zaehlt": "ja", "r": 14609}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Sam teilt ein 10 m langes Band in 3 gleich lange Stücke. Wie lang ist ein Stück, gerundet auf Zentimeter? Gib die Länge in Metern an."}, "o": {"wert": 3.33, "einheit": "m"}, "h": "Rechne 10 : 3. Die Ziffer 3 wiederholt sich immer wieder. Runde auf Hundertstel.", "w": "10 : 3 = 3,3333… Die Ziffer 3 wiederholt sich. Auf Hundertstel gerundet: 3,33 m.", "form": "anwenden", "zaehlt": "ja", "r": 14610}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Es gilt 4/11 = 0,363636… Die Ziffernfolge 36 wiederholt sich immer weiter. Wie groß ist die Summe aller Ziffern von der 1. bis zur 37. Stelle nach dem Komma?"}, "o": {"wert": 165}, "h": "Wie groß ist die Ziffernsumme einer Wiederholung? Wie viele ganze Wiederholungen passen in 37 Stellen, und welche Ziffer bleibt übrig?", "w": "Eine Wiederholung „36“ hat 2 Ziffern und die Ziffernsumme 3 + 6 = 9. In 37 Stellen passen 18 ganze Wiederholungen (36 Stellen): 18 · 9 = 162. Die 37. Stelle ist die erste Ziffer einer neuen Wiederholung, also 3. Summe: 162 + 3 = 165.", "form": "anwenden", "zaehlt": "ja", "r": 14611}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Es gilt 3/11 = 0,272727… Die Ziffernfolge 27 wiederholt sich immer weiter. Wie oft steht die Ziffer 7 unter den ersten 25 Nachkommastellen?"}, "o": {"wert": 12}, "h": "An welchen Stellen steht die 7? Wie viele gerade Zahlen gibt es bis 25?", "w": "Die Ziffern wechseln: 2, 7, 2, 7, … Die 7 steht an jeder zweiten Stelle, nämlich an den Stellen 2, 4, 6, …, 24. Das sind 12 Stellen. Die 25. Stelle ist eine 2.", "form": "anwenden", "zaehlt": "ja", "r": 14612}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Sam schätzt 4,98 · 2,02, indem er beide Zahlen auf ganze Zahlen rundet. Er behauptet: „Der Überschlag ist größer als das genaue Ergebnis.“ Prüfe das nach: Um wie viel unterscheiden sich der Überschlag und das genaue Ergebnis? Gib den Unterschied als Dezimalzahl an."}, "o": {"wert": 0.0596}, "h": "Berechne den Überschlag 5 · 2. Rechne das genaue Ergebnis ohne Komma als 498 · 202 und setze das Komma wieder ein: vier Nachkommastellen.", "w": "Überschlag: 5 · 2 = 10. Genau: 4,98 · 2,02 = 10,0596. Der Überschlag ist kleiner als das genaue Ergebnis, Sams Behauptung stimmt also nicht. Unterschied: 10,0596 − 10 = 0,0596.", "form": "anwenden", "zaehlt": "ja", "r": 14613}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf einem Zahlenstrahl liegt der Punkt A bei 4,35 und der Punkt B bei 4,47. M ist der Mittelpunkt der Strecke AB. Wie viele Zahlen mit genau zwei Nachkommastellen liegen zwischen M und B? M und B zählen nicht mit."}, "o": {"wert": 5}, "h": "Wie weit liegen A und B auseinander? Wo liegt M? Zähle die Hundertstel zwischen M und B.", "w": "A = 4,35 sind 435 Hundertstel, B = 4,47 sind 447 Hundertstel. Der Abstand ist 12 Hundertstel, die Hälfte 6: M liegt bei 441 Hundertsteln, also bei 4,41. Zwischen M und B liegen 4,42; 4,43; 4,44; 4,45; 4,46. Das sind 5 Zahlen.", "form": "anwenden", "zaehlt": "ja", "r": 14614}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "zahl", "f": {"text": "Kim behauptet: „Je mehr Ziffern nach dem Komma, desto größer ist die Zahl.“ Kim vergleicht 0,7 und 0,689. Um wie viele Tausendstel ist die Zahl mit weniger Ziffern größer?"}, "o": {"wert": 11, "einheit": "Tausendstel"}, "h": "Schreibe 0,7 als 0,700 und vergleiche mit 0,689 Stelle für Stelle.", "w": "0,7 = 0,700 = 700 Tausendstel. 0,689 sind 689 Tausendstel. Unterschied: 700 − 689 = 11 Tausendstel. Kims Aussage ist falsch.", "form": "anwenden", "zaehlt": "ja", "r": 14615}]$auf$::jsonb),
    (11, 'bruch.prozent', 621, 18, $auf$[{"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Der Ladebalken eines Tablets ist zu 3/5 gefüllt. Wie viel Prozent sind das?"}, "o": {"wert": 60, "einheit": "%"}, "h": "Prozent heißt Hundertstel. Erweitere den Bruch auf den Nenner 100.", "w": "3/5 = 60/100 (mit 20 erweitert). 60/100 sind 60 %. Der Akku ist zu 60 % geladen.", "form": "anwenden", "zaehlt": "ja", "r": 14622}, {"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Fruchtsaft besteht zu 35 % aus Orangensaft und zu 0,4 aus Apfelsaft. Der Rest ist Wasser. Wie viel Prozent des Safts sind Wasser?"}, "o": {"wert": 25, "einheit": "%"}, "h": "Schreibe alle Anteile als Prozentzahlen. Der ganze Saft sind 100 %.", "w": "0,4 = 40/100 = 40 %. Orangensaft und Apfelsaft zusammen: 35 % + 40 % = 75 %. Wasser: 100 % − 75 % = 25 %.", "form": "anwenden", "zaehlt": "ja", "r": 14623}, {"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Parkweg ist 80 m lang. Davon sind 0,25 asphaltiert und 15 % geschottert. Ein Fünftel des Weges ist Wiese. Der Rest ist ein Sandweg. Wie viele Meter ist der Sandweg lang?"}, "o": {"wert": 32, "einheit": "m"}, "h": "Schreibe alle Anteile als Prozent. Wie viel Prozent bleiben für den Sandweg?", "w": "0,25 = 25 %, 15 %, 1/5 = 20 %. Zusammen 25 % + 15 % + 20 % = 60 %. Der Sandweg ist 40 % des Weges: 40 % von 80 m = 0,4 · 80 = 32 m.", "form": "anwenden", "zaehlt": "ja", "r": 14624}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einer Schule mit 480 Kindern fahren 35 % mit dem Fahrrad zur Schule. Wie viele Kinder fahren mit dem Fahrrad?"}, "o": {"wert": 168, "einheit": "Kinder"}, "h": "Berechne zuerst 1 % der Kinder. Nimm das Ergebnis mal 35.", "w": "1 % von 480 sind 4,8 Kinder. 35 % sind 35 · 4,8 = 168 Kinder. Probe: 168 : 480 = 0,35.", "form": "anwenden", "zaehlt": "ja", "r": 14625}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Obsthändler hat 250 kg Äpfel. 12 % davon sind angefault und werden aussortiert. Wie viele Kilogramm Äpfel kann er verkaufen?"}, "o": {"wert": 220, "einheit": "kg"}, "h": "Berechne zuerst, wie viele Kilogramm aussortiert werden. Oder: Wie viel Prozent bleiben?", "w": "Aussortiert: 12 % von 250 kg = 30 kg. Es bleiben 250 − 30 = 220 kg. Oder: 88 % von 250 kg = 220 kg.", "form": "anwenden", "zaehlt": "ja", "r": 14626}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Chor mit 40 Kindern sind 60 % Mädchen. Von den Mädchen singen 25 % Alt. Wie viele Mädchen singen Alt?"}, "o": {"wert": 6, "einheit": "Mädchen"}, "h": "Bestimme zuerst, wie viele Mädchen im Chor sind. Von dieser Zahl nimmst du dann 25 %.", "w": "Mädchen: 60 % von 40 = 24. Davon 25 % = ein Viertel von 24 = 6. Sechs Mädchen singen Alt. Wichtig: Die 25 % beziehen sich auf die Mädchen, nicht auf alle 40 Kinder.", "form": "anwenden", "zaehlt": "ja", "r": 14627}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Noa beantwortet bei einem Quiz 33 von 44 Fragen richtig. Wie viel Prozent der Fragen hat Noa richtig beantwortet?"}, "o": {"wert": 75, "einheit": "%"}, "h": "Teile die richtigen Fragen durch alle Fragen. Dann rechnest du in Prozent um. Kürzen hilft: 33 und 44 haben einen gemeinsamen Teiler.", "w": "33 : 44 = 0,75 = 75 %. Oder: 33/44 = 3/4 (gekürzt mit 11) = 75/100 = 75 %.", "form": "anwenden", "zaehlt": "ja", "r": 14628}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Preis einer Eintrittskarte steigt von 250 € auf 280 €. Um wie viel Prozent ist der Preis gestiegen?"}, "o": {"wert": 12, "einheit": "%"}, "h": "Wie viel Euro ist der Preis gestiegen? Auf welchen Preis bezieht sich der Prozentsatz?", "w": "Die Erhöhung ist 280 − 250 = 30 €. Bezogen auf den alten Preis: 30 : 250 = 0,12 = 12 %.", "form": "anwenden", "zaehlt": "ja", "r": 14629}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Freibad hat an einem Tag 500 Besucher. 40 % davon sind Kinder. Von den Erwachsenen sind 90 Senioren. Wie viel Prozent aller Besucher sind erwachsene Nicht-Senioren?"}, "o": {"wert": 42, "einheit": "%"}, "h": "Wie viele der 500 Besucher sind Kinder? Wie viele sind erwachsen, aber keine Senioren?", "w": "Kinder: 40 % von 500 = 200. Erwachsene: 500 − 200 = 300. Davon sind 90 Senioren, also 300 − 90 = 210 erwachsene Nicht-Senioren. 210 : 500 = 0,42 = 42 %.", "form": "anwenden", "zaehlt": "ja", "r": 14630}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einem Orchester spielen 18 Kinder Geige. Das sind 30 % aller Kinder im Orchester. Wie viele Kinder spielen insgesamt im Orchester?"}, "o": {"wert": 60, "einheit": "Kinder"}, "h": "Wenn 30 % die Zahl 18 sind: Wie viele Kinder sind 1 %? Wie viele sind 100 %?", "w": "30 % sind 18 Kinder. 1 % sind 18 : 30 = 0,6 Kinder. 100 % sind 0,6 · 100 = 60 Kinder. Probe: 30 % von 60 = 18.", "form": "anwenden", "zaehlt": "ja", "r": 14631}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einem Wald sind 144 Bäume Buchen. Das sind 45 % aller Bäume. 15 % aller Bäume im Wald sind erkrankt. Wie viele Bäume sind erkrankt?"}, "o": {"wert": 48, "einheit": "Bäume"}, "h": "Berechne zuerst, wie viele Bäume es im Wald insgesamt gibt. Danach rechnest du mit 15 %.", "w": "45 % sind 144 Bäume, also 1 % = 3,2 Bäume und 100 % = 320 Bäume. 15 % von 320 = 48 Bäume sind erkrankt.", "form": "anwenden", "zaehlt": "ja", "r": 14632}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Verein hat 27 Kinder als Mitglieder. Das sind 15 % aller Mitglieder. 40 % aller Mitglieder sind Frauen. Wie viele Frauen sind Mitglied im Verein?"}, "o": {"wert": 72, "einheit": "Frauen"}, "h": "Berechne zuerst, wie viele Mitglieder der Verein insgesamt hat. Die 27 Kinder sind 15 %.", "w": "15 % sind 27 Kinder, 1 % sind 27 : 15 = 1,8. Alle Mitglieder (100 %): 1,8 · 100 = 180. Frauen: 40 % von 180 = 0,4 · 180 = 72.", "form": "anwenden", "zaehlt": "ja", "r": 14633}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Paar Kopfhörer kostet 90 €. Beim Schlussverkauf gibt es 30 % Rabatt. Wie viel Euro kosten die Kopfhörer jetzt?"}, "o": {"wert": 63, "einheit": "€"}, "h": "Wie viel Prozent vom alten Preis bezahlst du noch? Oder berechne den Rabatt in Euro und ziehe ihn ab.", "w": "Rabatt: 30 % von 90 € = 27 €. Neuer Preis: 90 − 27 = 63 €. Oder: 70 % von 90 € = 63 €.", "form": "anwenden", "zaehlt": "ja", "r": 14634}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spiel kostet 60 €. Im Angebot gibt es 20 % Rabatt. Kim hat außerdem einen Gutschein über 8 €. Der Gutschein wird erst nach dem Rabatt vom Preis abgezogen. Wie viel Euro zahlt Kim?"}, "o": {"wert": 40, "einheit": "€"}, "h": "Berechne zuerst den Preis nach dem Rabatt. Dann ziehst du den Gutschein ab.", "w": "Rabatt: 20 % von 60 € = 12 €. Preis nach dem Rabatt: 60 − 12 = 48 €. Gutschein: 48 − 8 = 40 €. Kim zahlt 40 €.", "form": "anwenden", "zaehlt": "ja", "r": 14635}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Alex vergleicht zwei Jacken. Bei Jacke A beträgt der Rabatt von 30 % genau 36 €. Jacke B kostet 95 € ohne Rabatt. Um wie viel Euro ist Jacke A nach dem Rabatt günstiger als Jacke B?"}, "o": {"wert": 11, "einheit": "€"}, "h": "Die 36 € sind 30 % des alten Preises. Wie viel Euro sind 10 %, wie viel 100 %? Dann berechnest du den Preis nach dem Rabatt.", "w": "30 % sind 36 €, also sind 10 % genau 12 € und 100 % genau 120 €. Jacke A kostet nach dem Rabatt 120 − 36 = 84 €. Jacke B kostet 95 €. Unterschied: 95 − 84 = 11 €.", "form": "anwenden", "zaehlt": "ja", "r": 14636}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim sagt: „Beide Läden geben 20 % Rabatt auf eine Jacke, also spare ich in beiden Läden gleich viel.“ Im Laden A kostet die Jacke 80 €, im Laden B kostet sie 120 €. Wie viel Euro spart man in Laden B mehr als in Laden A?"}, "o": {"wert": 8, "einheit": "€"}, "h": "20 % sind immer 20 % von einem Preis. Berechne die Ersparnis für beide Jacken einzeln.", "w": "Laden A: 20 % von 80 € = 16 €. Laden B: 20 % von 120 € = 24 €. Unterschied: 24 − 16 = 8 €. Gleiche Prozentzahl heißt nicht gleich viel Euro, wenn die Preise verschieden sind.", "form": "anwenden", "zaehlt": "ja", "r": 14637}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Mannschaft A gewinnt 9 von 12 Spielen. Die Mannschaft B gewinnt 18 von 25 Spielen. Um wie viele Prozentpunkte ist der Anteil gewonnener Spiele bei A größer als bei B?"}, "o": {"wert": 3, "einheit": "Prozentpunkte"}, "h": "B hat mehr Spiele gewonnen, hat aber auch mehr gespielt. Vergleiche die Anteile in Prozent.", "w": "A: 9 : 12 = 0,75 = 75 %. B: 18 : 25 = 0,72 = 72 %. Unterschied: 75 − 72 = 3 Prozentpunkte. A gewinnt anteilig öfter, obwohl B mehr Siege hat.", "form": "anwenden", "zaehlt": "ja", "r": 14638}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Kim behauptet: „Der Anteil 7/20 sind 75 %.“ Um wie viele Prozentpunkte ist Kims Angabe zu groß?"}, "o": {"wert": 40, "einheit": "Prozentpunkte"}, "h": "Rechne 7/20 in Prozent um: Erweitere auf den Nenner 100. Dann vergleichst du mit Kims 75 %.", "w": "7/20 = 35/100 = 35 %. Kim hat 75 % gesagt, das sind 75 − 35 = 40 Prozentpunkte zu viel.", "form": "anwenden", "zaehlt": "ja", "r": 14639}]$auf$::jsonb),
    (31, 'stochastik.grundbegriffe', 590, 9, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Aus einem Beutel mit fünf verschiedenfarbigen Kugeln (rot, blau, gelb, grün, weiß) werden nacheinander zwei Kugeln ohne Zurücklegen gezogen. Die Reihenfolge der Farben zählt. Wie viele Ergebnisse hat der Ergebnisraum?"}, "o": {"wert": 20, "einheit": "Ergebnisse"}, "h": "Wie viele Möglichkeiten gibt es für die erste Kugel? Wie viele bleiben dann für die zweite?", "w": "Für die erste Kugel gibt es 5 Möglichkeiten, für die zweite danach noch 4. Das sind 5 · 4 = 20 Ergebnisse, zum Beispiel (rot | blau) und (blau | rot).", "form": "anwenden", "zaehlt": "ja", "r": 14591}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Würfel mit den Augenzahlen 1 bis 6 und eine Münze (Seiten „Wappen“ und „Zahl“) werden einmal geworfen. Ein Ergebnis ist ein Paar aus Augenzahl und Münzseite, zum Beispiel (5 | Wappen). Wie viele Ergebnisse gehören zum Ereignis „Die Augenzahl ist größer als 4 oder die Münze zeigt Wappen“?"}, "o": {"wert": 8, "einheit": "Ergebnisse"}, "h": "Zähle zuerst die Ergebnisse mit Würfelzahl 5 oder 6. Zähle dann die Ergebnisse mit Wappen. Was wurde doppelt gezählt?", "w": "Augenzahl größer als 4: Das sind 5 und 6, jeweils mit Wappen oder Zahl, also 4 Ergebnisse. Wappen: 6 Ergebnisse (jede Augenzahl mit Wappen). Doppelt gezählt: (5 | Wappen) und (6 | Wappen), also 2. Zusammen 4 + 6 − 2 = 8. Probe: Nicht dazu gehören nur die Augenzahlen 1 bis 4 mit der Münzseite Zahl, das sind 4 von 12 Ergebnissen.", "form": "anwenden", "zaehlt": "ja", "r": 14592}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Glücksrad hat 30 gleich große Felder mit den Nummern 1 bis 30. Ereignis A: „Die Nummer ist ein Vielfaches von 3“. Ereignis B: „Die Nummer ist ein Vielfaches von 5“. Wie viele Ergebnisse gehören zu genau einem der beiden Ereignisse (zu A oder zu B, aber nicht zu beiden)?"}, "o": {"wert": 12, "einheit": "Ergebnisse"}, "h": "Zähle die Vielfachen von 3 und die von 5. Welche Nummern stehen in beiden Gruppen?", "w": "A: 3, 6, …, 30, das sind 10. B: 5, 10, …, 30, das sind 6. In beiden stehen 15 und 30, also 2. Nur A: 10 − 2 = 8. Nur B: 6 − 2 = 4. Genau eines der beiden: 8 + 4 = 12 Ergebnisse.", "form": "anwenden", "zaehlt": "ja", "r": 14593}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Sam wirft beim Training 40-mal einen Basketball auf den Korb und trifft 28-mal. Wie groß ist die relative Häufigkeit der Treffer in Prozent?"}, "o": {"wert": 70, "einheit": "%"}, "h": "Relative Häufigkeit = Zahl der Treffer geteilt durch Zahl der Versuche. Dann in Prozent umrechnen.", "w": "28 : 40 = 0,7. Als Prozent: 0,7 · 100 = 70 %. Sam trifft in 70 % der Fälle.", "form": "anwenden", "zaehlt": "ja", "r": 14594}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim würfelt in zwei Serien. In der ersten Serie sind es 50 Würfe, dabei fällt 18-mal die Sechs. In der zweiten Serie sind es 150 Würfe, dabei fällt 21-mal die Sechs. Wie groß ist die relative Häufigkeit der Sechs über beide Serien zusammen in Prozent?"}, "o": {"wert": 19.5, "einheit": "%"}, "h": "Zähle die Sechsen aller Würfe zusammen und teile durch die Zahl aller Würfe.", "w": "Sechsen: 18 + 21 = 39. Würfe: 50 + 150 = 200. Relative Häufigkeit: 39 : 200 = 0,195 = 19,5 %.", "form": "anwenden", "zaehlt": "ja", "r": 14595}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Spielerin A trifft bei 24 Würfen 18-mal. Spieler B trifft bei 40 Würfen 25-mal. Um wie viele Prozentpunkte ist die relative Häufigkeit der Treffer bei A größer als bei B?"}, "o": {"wert": 12.5, "einheit": "Prozentpunkte"}, "h": "Die Zahlen der Würfe sind verschieden. Vergleiche deshalb die relativen Häufigkeiten in Prozent.", "w": "A: 18 : 24 = 0,75 = 75 %. B: 25 : 40 = 0,625 = 62,5 %. Unterschied: 75 − 62,5 = 12,5 Prozentpunkte. A hat die höhere Trefferquote, obwohl B mehr Treffer hat.", "form": "anwenden", "zaehlt": "ja", "r": 14596}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einer Klasse mit 25 Kindern sind 14 Mädchen. 9 Kinder tragen eine Brille, darunter 5 Mädchen. Eine Vierfeldertafel zeigt: Mädchen mit Brille, Mädchen ohne Brille, Jungen mit Brille, Jungen ohne Brille. Wie viele Jungen tragen keine Brille?"}, "o": {"wert": 7, "einheit": "Jungen"}, "h": "Trage die bekannten Zahlen in eine Vierfeldertafel ein. Rechne zuerst die Zahl der Jungen und die der Jungen mit Brille aus.", "w": "Jungen: 25 − 14 = 11. Jungen mit Brille: 9 − 5 = 4. Jungen ohne Brille: 11 − 4 = 7. Probe: Mädchen mit Brille 5 + Mädchen ohne Brille 9 + Jungen mit Brille 4 + Jungen ohne Brille 7 = 25.", "form": "anwenden", "zaehlt": "ja", "r": 14597}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Bei einem Spiel wird zuerst ein Würfel mit den Zahlen 1 bis 6 geworfen. Bei einer geraden Zahl wird danach eine Münze geworfen. Bei einer ungeraden Zahl wird danach ein Würfel mit den Zahlen 1 bis 4 geworfen. Das Spiel wird als Baumdiagramm gezeichnet. Wie viele Wege hat es?"}, "o": {"wert": 18, "einheit": "Wege"}, "h": "Wie viele Äste gehen von der ersten Verzweigung aus? Zähle für jede Gruppe die Wege getrennt.", "w": "Gerade Zahlen: 2, 4, 6 – das sind 3, dann 2 Münzseiten: 3 · 2 = 6 Wege. Ungerade Zahlen: 1, 3, 5 – das sind 3, dann 4 Zahlen: 3 · 4 = 12 Wege. Zusammen 6 + 12 = 18 Wege.", "form": "anwenden", "zaehlt": "ja", "r": 14598}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einer Gruppe von 100 Personen sind 60 Frauen. 30 Personen kommen mit dem Rad. Unter den Radfahrern sind doppelt so viele Frauen wie Männer. Wie viel Prozent der Männer kommen nicht mit dem Rad?"}, "o": {"wert": 75, "einheit": "%"}, "h": "Zeichne eine Vierfeldertafel mit „Frau / Mann“ und „Rad / nicht Rad“. Wie viele Männer fahren Rad? Rechne mit den 30 Radfahrern in zwei Teilen.", "w": "Männer insgesamt: 100 − 60 = 40. Die Radfahrer sind in drei gleiche Teile geteilt: 2 Teile Frauen, 1 Teil Männer. Männer mit Rad: 30 : 3 = 10. Männer ohne Rad: 40 − 10 = 30. Anteil: 30 : 40 = 0,75 = 75 %.", "form": "anwenden", "zaehlt": "ja", "r": 14599}]$auf$::jsonb),
    (52, 'messen.koerper_berechnung', 552, 15, $auf$[{"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Kantenmodell aus Draht wird ein Würfel mit der Kantenlänge 7 cm gebaut. Jede Kante des Würfels ist ein Drahtstück. Wie viele Zentimeter Draht braucht man insgesamt?"}, "o": {"wert": 84, "einheit": "cm"}, "h": "Wie viele Kanten hat ein Würfel? Alle Kanten sind gleich lang.", "w": "Ein Würfel hat 12 Kanten, jede ist 7 cm lang. Draht: 12 · 7 = 84 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14553}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Aus einem 1,5 m langen Draht wird das Kantenmodell eines Quaders gebaut. Der Quader ist 12 cm lang, 8 cm breit und 5 cm hoch. Wie viele Zentimeter Draht bleiben übrig?"}, "o": {"wert": 50, "einheit": "cm"}, "h": "Wie viele Kanten gleicher Länge gibt es von jeder Sorte? Rechne zuerst in Zentimetern.", "w": "Von jeder Sorte (Länge, Breite, Höhe) gibt es 4 Kanten. Draht für das Modell: 4 · (12 + 8 + 5) = 4 · 25 = 100 cm. 1,5 m = 150 cm. Es bleiben 150 − 100 = 50 cm übrig.", "form": "anwenden", "zaehlt": "ja", "r": 14554}, {"l": "quader", "t": "quader", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Quader ist 9 cm lang und 6 cm breit. Sein Volumen ist 270 cm³. Wie viele Zentimeter Draht braucht man für ein Kantenmodell dieses Quaders?"}, "o": {"wert": 80, "einheit": "cm"}, "h": "Berechne zuerst die fehlende Höhe aus dem Volumen. Danach zählst du alle 12 Kanten.", "w": "Höhe: 270 : (9 · 6) = 270 : 54 = 5 cm. Von jeder Sorte gibt es 4 Kanten: 4 · (9 + 6 + 5) = 4 · 20 = 80 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14555}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für einen würfelförmigen Blumenkasten ohne Deckel werden 80 dm² Holz gebraucht, ohne Verschnitt. Wie lang ist eine Kante des Kastens in Dezimetern?"}, "o": {"wert": 4, "einheit": "dm"}, "h": "Ein Kasten ohne Deckel hat nur 5 Flächen. Wie groß ist eine davon? Welche Zahl mal sich selbst ergibt diese Fläche?", "w": "80 : 5 = 16 dm² ist eine Fläche. Wegen 4 · 4 = 16 ist die Kante 4 dm lang. Probe: 5 · 4 · 4 = 80.", "form": "anwenden", "zaehlt": "ja", "r": 14556}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Schrank ist ein Quader: 1,2 m breit, 0,5 m tief und 2 m hoch. Die Vorderseite, die beiden Seitenwände und die Decke werden gestrichen. Die Rückwand steht an der Wand, der Boden ist unten. Wie viele Quadratmeter werden gestrichen?"}, "o": {"wert": 5, "einheit": "m²"}, "h": "Welche Flächen werden gestrichen? Berechne jede einzeln, auch die beiden gleichen Seitenwände.", "w": "Vorderseite: 1,2 · 2 = 2,4 m². Zwei Seitenwände: 2 · (0,5 · 2) = 2 m². Decke: 1,2 · 0,5 = 0,6 m². Zusammen 2,4 + 2 + 0,6 = 5 m².", "form": "anwenden", "zaehlt": "ja", "r": 14557}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Würfel mit 6 cm Kantenlänge und ein Quader haben dieselbe Oberfläche. Der Quader ist 10 cm lang und 6 cm breit. Wie hoch ist der Quader in Zentimetern?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Berechne zuerst die Oberfläche des Würfels. Beim Quader sind Boden und Deckel zusammen 2 · 10 · 6 groß. Was bleibt für den Mantel?", "w": "Würfel: 6 · 6 · 6 = 216 cm². Quader: Boden und Deckel 2 · 10 · 6 = 120 cm². Rest für den Mantel: 216 − 120 = 96 cm². Mantel: 2 · 10 · h + 2 · 6 · h = 32h = 96, also h = 3 cm. Probe: 2 · (60 + 30 + 18) = 216.", "form": "anwenden", "zaehlt": "ja", "r": 14558}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Regalfach ist vorne offen und 80 cm breit, 30 cm tief und 40 cm hoch. Boden, Decke, Rückwand und beide Seitenwände sind aus Holz. Wie viele Quadratzentimeter Holz werden gebraucht?"}, "o": {"wert": 10400, "einheit": "cm²"}, "h": "Welche fünf Flächen sind aus Holz? Berechne Boden und Decke zusammen, die Rückwand und die zwei Seitenwände.", "w": "Boden und Decke: 2 · 80 · 30 = 4 800 cm². Rückwand: 80 · 40 = 3 200 cm². Zwei Seitenwände: 2 · 30 · 40 = 2 400 cm². Zusammen 4 800 + 3 200 + 2 400 = 10 400 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14559}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Zimmer ist 6 m lang, 4 m breit und 2,5 m hoch. Die vier Wände werden gestrichen. Die Tür (2 m²) und das Fenster (3 m²) werden nicht gestrichen. Ein Eimer Farbe reicht für 12 m². Wie viele Eimer muss man mindestens kaufen?"}, "o": {"wert": 4, "einheit": "Eimer"}, "h": "Berechne die Fläche der vier Wände und ziehe Tür und Fenster ab. Teile durch 12 und überlege, wie viele ganze Eimer nötig sind.", "w": "Wände: 2 · (6 · 2,5) + 2 · (4 · 2,5) = 30 + 20 = 50 m². Ohne Tür und Fenster: 50 − 5 = 45 m². 45 : 12 = 3,75. Man braucht ganze Eimer, also 4 Eimer.", "form": "anwenden", "zaehlt": "ja", "r": 14560}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Regal ist ein Quader: 1,5 m breit, 0,6 m tief und 2 m hoch. Es hat keine Vorderseite. Rückwand: eine dünne Platte, 4 € je m². Boden, Decke und die beiden Seitenwände: Holz, 12 € je m². Wie viel Euro kosten alle Platten zusammen?"}, "o": {"wert": 62.4, "einheit": "€"}, "h": "Teile die Flächen nach dem Preis. Welche Flächen sind Holz, welche ist die dünne Platte?", "w": "Holz: Boden und Decke 2 · 1,5 · 0,6 = 1,8 m², zwei Seitenwände 2 · 0,6 · 2 = 2,4 m², zusammen 4,2 m². Preis: 4,2 · 12 = 50,4 €. Rückwand: 1,5 · 2 = 3 m², Preis: 3 · 4 = 12 €. Zusammen 50,4 + 12 = 62,4 €.", "form": "anwenden", "zaehlt": "ja", "r": 14561}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Holzwürfel hat 6 cm Kantenlänge. Von oben nach unten wird ein quadratisches Loch mit 2 cm Seitenlänge ganz durchgebohrt. Wie groß ist die Oberfläche des durchbohrten Würfels, mit den Wänden im Loch?"}, "o": {"wert": 256, "einheit": "cm²"}, "h": "Berechne die Oberfläche des Würfels. Zwei Öffnungen fallen weg, dafür kommen die Wände im Loch dazu.", "w": "Würfel: 6 · 36 = 216 cm². Die zwei Öffnungen (je 2 · 2 = 4 cm²) fallen weg: 216 − 8 = 208 cm². Das Loch hat 4 Wände, jede 2 · 6 = 12 cm²: 48 cm². Zusammen 208 + 48 = 256 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14562}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Treppenmodell besteht aus drei Türmen aus Würfeln mit 2 cm Kantenlänge, die in einer Reihe nebeneinander stehen und mit ganzen Flächen zusammengeklebt sind: Der erste Turm hat 1 Würfel, der zweite 2 Würfel und der dritte 3 Würfel übereinander. Wie groß ist die Oberfläche des Modells?"}, "o": {"wert": 96, "einheit": "cm²"}, "h": "Wie viele Würfelflächen siehst du von vorn, von hinten, von oben, von unten und von beiden Seiten? Eine Würfelfläche hat 2 · 2 = 4 cm².", "w": "Von vorn sehen wir 1 + 2 + 3 = 6 Würfelflächen, von hinten ebenso 6. Von oben sind es 3 (je Turm eine), von unten 3. Von der linken Seite sieht man 3 Flächen (vom ersten Turm 1 und vom zweiten und dritten Turm je 1 oberhalb des Nachbarturms), von der rechten Seite ebenfalls 3 (nur der dritte Turm). Zusammen 6 + 6 + 3 + 3 + 3 + 3 = 24 Würfelflächen zu je 4 cm²: 24 · 4 = 96 cm². Gegenprobe: 6 Würfel haben 36 Flächen, die 6 Klebestellen verdecken 12 davon: 36 − 12 = 24.", "form": "anwenden", "zaehlt": "ja", "r": 14563}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "begruenden", "y": "zahl", "f": {"text": "Aus einem Quader (5 cm lang, 4 cm breit, 3 cm hoch) wird an einer Ecke ein Würfel mit 2 cm Kantenlänge herausgesägt. Wie verändert sich die Oberfläche durch das Heraussägen? Gib den Unterschied „Oberfläche nachher minus Oberfläche vorher“ in cm² an."}, "o": {"wert": 0, "einheit": "cm²"}, "h": "Welche Flächen gehen an der Ecke verloren? Welche neuen Flächen entstehen im Ausschnitt? Vergleiche ihre Größen.", "w": "An der Ecke verschwinden 3 Quadrate des Quaders (je 2 · 2 = 4 cm²), zusammen 12 cm². Im Ausschnitt entstehen 3 neue Quadrate (je 4 cm²), zusammen 12 cm². Die Oberfläche bleibt gleich: 12 − 12 = 0 cm² mehr. Das gilt, solange der Würfel an einer Ecke herausgeschnitten wird.", "form": "anwenden", "zaehlt": "ja", "r": 14564}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim sagt: „Wenn man bei einem Würfel die Kante verdoppelt, wird auch die Oberfläche doppelt so groß.“ Ein Würfel hat die Kantenlänge 3 cm. Die Kante wird auf 6 cm verdoppelt. Wie groß ist die neue Oberfläche in cm²?"}, "o": {"wert": 216, "einheit": "cm²"}, "h": "Berechne die neue Oberfläche direkt mit der neuen Kante. Vergleiche mit der alten Oberfläche.", "w": "Neue Oberfläche: 6 · 6 · 6 = 216 cm². Alte Oberfläche: 6 · 3 · 3 = 54 cm². 216 : 54 = 4. Die Oberfläche wird 4-mal so groß, nicht 2-mal. Kims Aussage stimmt nicht.", "form": "anwenden", "zaehlt": "ja", "r": 14565}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ist 4 cm lang, 3 cm breit und 2 cm hoch. Die Höhe wird auf 4 cm verdoppelt, Länge und Breite bleiben gleich. Um wie viele Quadratzentimeter wird die Oberfläche größer?"}, "o": {"wert": 28, "einheit": "cm²"}, "h": "Berechne die Oberfläche vorher und nachher. Bilde dann die Differenz.", "w": "Vorher: 2 · (12 + 8 + 6) = 52 cm². Nachher: 2 · (12 + 16 + 12) = 80 cm². Unterschied: 80 − 52 = 28 cm². Die Oberfläche wird nicht doppelt so groß.", "form": "anwenden", "zaehlt": "ja", "r": 14566}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Zwei Quader haben beide das Volumen 120 cm³. Quader A ist 10 cm lang, 4 cm breit und 3 cm hoch. Quader B ist 6 cm lang, 5 cm breit und 4 cm hoch. Um wie viele Quadratzentimeter ist die Oberfläche von A größer als die von B?"}, "o": {"wert": 16, "einheit": "cm²"}, "h": "Gleiches Volumen bedeutet nicht gleiche Oberfläche. Berechne beide Oberflächen einzeln.", "w": "A: 2 · (40 + 30 + 12) = 164 cm². B: 2 · (30 + 24 + 20) = 148 cm². Unterschied: 164 − 148 = 16 cm². Beide Volumina sind gleich (10 · 4 · 3 = 120 = 6 · 5 · 4), aber der gedrungenere Quader B hat die kleinere Oberfläche.", "form": "anwenden", "zaehlt": "ja", "r": 14567}]$auf$::jsonb),
    (59, 'terme.aufstellen', 534, 18, $auf$[{"l": "struktur", "t": "struktur", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim schreibt vier Terme auf: A: 3 + x · 2, B: (3 + x) · 2, C: 3 · x + 2 · x, D: 12 : (x − 1). Alex bestimmt für jeden Term die zuletzt ausgeführte Rechenart und gibt eine Kennzahl: Summe = 1, Differenz = 2, Produkt = 3, Quotient = 4. Wie groß ist die Summe der vier Kennzahlen?"}, "o": {"wert": 9}, "h": "Welche Rechenart wird bei jedem Term zuletzt ausgeführt? Beachte Punkt vor Strich und die Klammern.", "w": "A: Erst x · 2, zuletzt wird 3 addiert: Summe (1). B: Erst die Klammer, zuletzt mal 2: Produkt (3). C: Erst 3 · x und 2 · x, zuletzt addiert: Summe (1). D: Erst die Klammer x − 1, zuletzt geteilt: Quotient (4). Zusammen 1 + 3 + 1 + 4 = 9.", "form": "anwenden", "zaehlt": "ja", "r": 14535}, {"l": "struktur", "t": "struktur", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Term 36 : (x − 3) + 2 · x wird für x = 9 berechnet. Er ist eine Summe aus zwei Summanden. Wie groß ist der größere Summand?"}, "o": {"wert": 18}, "h": "Welche zwei Summanden hat der Term? Berechne beide für x = 9.", "w": "Die Summe hat zwei Summanden: 36 : (x − 3) und 2 · x. Für x = 9 ist der erste 36 : 6 = 6 und der zweite 2 · 9 = 18. Der größere Summand ist 18.", "form": "anwenden", "zaehlt": "ja", "r": 14536}, {"l": "struktur", "t": "struktur", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Kim bestimmt die Art von vier Termen. (1) 2 + 3 · x ist eine Summe. (2) (2 + 3) · x ist eine Summe. (3) 12 : x − 2 ist ein Quotient. (4) 5 · (x − 2) ist ein Produkt. Einige Aussagen sind falsch. Wie groß ist die Summe der Nummern der falschen Aussagen?"}, "o": {"wert": 5}, "h": "Bestimme bei jedem Term die Rechenart, die zuletzt ausgeführt wird.", "w": "(1) Erst 3 · x, zuletzt +: Summe, richtig. (2) Erst die Klammer 2 + 3, zuletzt mal x: ein Produkt, also falsch. (3) Erst 12 : x, zuletzt − 2: eine Differenz, also falsch. (4) Erst die Klammer, zuletzt mal 5: Produkt, richtig. Falsch sind (2) und (3): 2 + 3 = 5.", "form": "anwenden", "zaehlt": "ja", "r": 14537}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Handyvertrag kostet 5 € Grundgebühr im Monat und 0,05 € für jede Minute. Der Preis in Euro ist 5 + 0,05 · m, wobei m die Zahl der Minuten ist. Wie viel Euro kostet der Vertrag bei m = 120 Minuten?"}, "o": {"wert": 11, "einheit": "€"}, "h": "Setze m = 120 ein. Rechne Punktrechnung vor Strichrechnung.", "w": "5 + 0,05 · 120 = 5 + 6 = 11. Der Vertrag kostet 11 €.", "form": "anwenden", "zaehlt": "ja", "r": 14538}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Vor zwei Wochen hatte Alex 50 € auf dem Konto. Seitdem werden jede Woche 4 € abgebucht. Das Guthaben in Euro wird t Wochen ab heute durch den Term 50 − 4 · (t + 2) angegeben. Wie viel Euro sind es nach t = 3 Wochen?"}, "o": {"wert": 30, "einheit": "€"}, "h": "Die Klammer kommt zuerst. Dann die Multiplikation, zuletzt die Subtraktion.", "w": "Klammer: 3 + 2 = 5. Dann 4 · 5 = 20. Dann 50 − 20 = 30. Alex hat 30 €.", "form": "anwenden", "zaehlt": "ja", "r": 14539}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Aus einem Tank laufen Liter ab. Nach t Minuten sind noch 120 − 3 · (2t + 5) Liter im Tank. Nach wie vielen Minuten sind noch genau 63 Liter im Tank?"}, "o": {"wert": 7, "einheit": "Minuten"}, "h": "Setze den Term gleich 63. Arbeite von außen nach innen rückwärts: Was kommt zuletzt, was zuerst?", "w": "Rückwärts rechnen: Von 120 Litern sind 120 − 63 = 57 Liter abgeflossen. Das sind 3 mal etwas: 57 : 3 = 19 ist der Wert der Klammer 2t + 5. Davon 5 abziehen: 19 − 5 = 14 ist 2t, also ist t = 14 : 2 = 7 Minuten. Probe: 2 · 7 + 5 = 19, 3 · 19 = 57, 120 − 57 = 63.", "form": "anwenden", "zaehlt": "ja", "r": 14540}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim denkt sich die Zahl 8. Sie bildet die Summe aus dem Doppelten dieser Zahl und 7. Welches Ergebnis erhält Kim?"}, "o": {"wert": 23}, "h": "Übersetze Wort für Wort: das Doppelte der Zahl heißt 2 mal die Zahl. Dazu kommt 7.", "w": "Das Doppelte von 8 ist 2 · 8 = 16. Die Summe aus 16 und 7 ist 23. Als Term: 2x + 7 mit x = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14541}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim übersetzt: „Das Doppelte der Differenz aus x und 4, dazu das Dreifache von x.“ Welchen Wert hat der Term für x = 10?"}, "o": {"wert": 42}, "h": "Die Differenz aus x und 4 heißt x − 4 (in dieser Reihenfolge). Davon das Doppelte braucht eine Klammer.", "w": "Term: 2 · (x − 4) + 3x. Für x = 10: 2 · 6 + 30 = 12 + 30 = 42.", "form": "anwenden", "zaehlt": "ja", "r": 14542}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Rechteck ist x cm breit. Die Länge ist 5 cm länger als das Doppelte der Breite. Der Umfang beträgt 70 cm. Wie breit ist das Rechteck in Zentimetern?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Rechne mit dem halben Umfang: Breite plus Länge. Wie viele Breiten und wie viele Zentimeter stecken in der Länge? Probiere Breiten aus oder rechne rückwärts.", "w": "Der halbe Umfang ist 35 cm: Breite plus Länge. Die Länge ist 2 Breiten und 5 cm. Probiere: Bei 5 cm Breite ist die Länge 15 cm und Breite plus Länge 20 cm (zu wenig). Bei 10 cm Breite ist die Länge 25 cm und Breite plus Länge 35 cm (stimmt). Rückwärts: 35 − 5 = 30 cm sind 3 Breiten, also ist die Breite 30 : 3 = 10 cm. Probe: Umfang 2 · (10 + 25) = 70.", "form": "anwenden", "zaehlt": "ja", "r": 14543}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Lieferdienst berechnet 2,50 € Liefergebühr und 8 € für jede Pizza. Wie viel Euro kosten 3 Pizzen mit Lieferung?"}, "o": {"wert": 26.5, "einheit": "€"}, "h": "Die Liefergebühr zahlt man nur einmal. Die 8 € zahlt man für jede Pizza.", "w": "Die Pizzen kosten 3 · 8 = 24 €. Dazu kommt die Liefergebühr 2,50 €. Zusammen 24 + 2,50 = 26,50 €. Als Term: 2,5 + 8 · x mit x = 3.", "form": "anwenden", "zaehlt": "ja", "r": 14544}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf Kims Sparbuch liegen 120 €. Jede Woche kommen 15 € dazu. Nach der 4. Woche werden einmal 30 € abgehoben. Wie viel Euro sind nach 8 Wochen auf dem Sparbuch?"}, "o": {"wert": 210, "einheit": "€"}, "h": "Wie oft kommen 15 € dazu? Die 30 € werden nur einmal abgehoben.", "w": "Einzahlungen: 8 · 15 = 120 €. Startbetrag 120 €. Eine Abhebung: −30 €. Gesamt: 120 + 120 − 30 = 210 €.", "form": "anwenden", "zaehlt": "ja", "r": 14545}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Kletterhalle hat zwei Angebote. Gruppenkarte: 36 € Grundpreis und 4 € je Person. Einzelkarten: 10 € je Person. Ab wie vielen Personen ist die Gruppenkarte günstiger als die Einzelkarten?"}, "o": {"wert": 7, "einheit": "Personen"}, "h": "Rechne für 5, 6 und 7 Personen aus, was beide Angebote kosten. Wann sind sie gleich teuer, ab wann ist die Gruppenkarte günstiger?", "w": "Probiere mit einer Tabelle (Gruppe: 36 + 4 je Person, einzeln: 10 je Person): 5 Personen 56 € und 50 €, 6 Personen 60 € und 60 € (gleich teuer), 7 Personen 64 € und 70 €. Erst ab 7 Personen ist die Gruppenkarte günstiger.", "form": "anwenden", "zaehlt": "ja", "r": 14546}, {"l": "muster", "t": "muster", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Becher werden ineinander gestapelt. Ein einzelner Becher ist 12 cm hoch. Ein Stapel aus 2 Bechern ist 14 cm hoch, ein Stapel aus 3 Bechern ist 16 cm hoch. So geht es weiter. Wie hoch ist ein Stapel aus 15 Bechern in Zentimetern?"}, "o": {"wert": 40, "einheit": "cm"}, "h": "Um wie viele Zentimeter wächst der Stapel mit jedem weiteren Becher? Prüfe deinen Term mit 3 Bechern.", "w": "Mit jedem weiteren Becher wächst der Stapel um 2 cm. Der Term ist 2n + 10. Probe: n = 1 gibt 12, n = 2 gibt 14, n = 3 gibt 16. Für n = 15: 2 · 15 + 10 = 40 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14547}, {"l": "muster", "t": "muster", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Perlenketten wachsen nach einem Muster: Figur 1 hat 7 Perlen, Figur 2 hat 13 Perlen, Figur 3 hat 19 Perlen. So geht es weiter. Ab welcher Figur hat die Kette mehr als 100 Perlen?"}, "o": {"wert": 17}, "h": "Um wie viele Perlen wird die Kette von Figur zu Figur länger? Stelle den Term auf und probiere, wann 100 überschritten wird.", "w": "Es kommen immer 6 Perlen dazu. Der Term ist 6n + 1. Probe: n = 1 gibt 7, n = 2 gibt 13, n = 3 gibt 19. Probieren: Figur 16 hat 6 · 16 + 1 = 97 Perlen (zu wenig), Figur 17 hat 6 · 17 + 1 = 103 Perlen. Ab Figur 17 sind es mehr als 100.", "form": "anwenden", "zaehlt": "ja", "r": 14548}, {"l": "muster", "t": "muster", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Zwei Muster aus Plättchen: Muster A hat bei Figur n genau 4n + 2 Plättchen. Muster B hat bei Figur n genau 6n − 4 Plättchen. Bei welcher Figur haben beide Muster gleich viele Plättchen?"}, "o": {"wert": 3}, "h": "Berechne beide Muster für n = 1, 2, 3, … in einer Tabelle. Wo stehen gleiche Zahlen?", "w": "Lege eine Tabelle an. Figur 1: Muster A 6, Muster B 2. Figur 2: A 10, B 8. Figur 3: A 14, B 14. Bei Figur 3 sind beide gleich. Danach ist B immer größer, weil B bei jeder Figur 2 Plättchen mehr dazubekommt als A.", "form": "anwenden", "zaehlt": "ja", "r": 14549}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Der Term 40 − 5t gibt an, wie viele Kilometer noch bis zum Ziel fehlen, wenn eine Wandergruppe t Stunden unterwegs ist. Wie viele Kilometer wandert die Gruppe in jeder Stunde?"}, "o": {"wert": 5, "einheit": "km"}, "h": "Wie ändert sich der Term, wenn t um 1 größer wird? Was bedeutet die Zahl vor dem t?", "w": "Wenn t um 1 wächst, wird 5t um 5 größer und der Term um 5 kleiner. Die Zahl vor dem t zählt pro Stunde: Die Gruppe wandert 5 km in jeder Stunde. Die 40 ist die Strecke am Anfang.", "form": "anwenden", "zaehlt": "ja", "r": 14550}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Wassermenge in einem Tank in Litern ist nach t Minuten 80 − 5t. Wie viele Minuten dauert es länger, bis der Tank ganz leer ist, als bis nur noch 35 Liter im Tank sind?"}, "o": {"wert": 7, "einheit": "Minuten"}, "h": "Wann ist der Tank leer, wann sind noch 35 Liter darin? Probiere oder rechne rückwärts: Wie viele Liter sind bis dahin abgeflossen?", "w": "Leer: 80 Liter sind abgeflossen, bei 5 Litern je Minute nach 80 : 5 = 16 Minuten. Noch 35 Liter: 80 − 35 = 45 Liter sind abgeflossen, nach 45 : 5 = 9 Minuten. Der Unterschied ist 16 − 9 = 7 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 14551}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Kim übersetzt „das Doppelte der Summe aus x und 3“ in den Term 2x + 3. Der richtige Term ist 2 · (x + 3). Um wie viel unterscheiden sich die beiden Werte für x = 5?"}, "o": {"wert": 3}, "h": "Berechne beide Terme einzeln für x = 5. Was wird bei Kims Term nur einmal und was zweimal gerechnet?", "w": "Kims Term: 2 · 5 + 3 = 13. Richtiger Term: 2 · (5 + 3) = 16. Unterschied: 16 − 13 = 3. Der Fehler: Im richtigen Term wird auch die 3 verdoppelt, bei Kim nicht.", "form": "anwenden", "zaehlt": "ja", "r": 14552}]$auf$::jsonb),
    (93, 'messen.flaechen_vielecke', 375, 24, $auf$[{"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Fensterscheibe hat die Form eines Parallelogramms. Die Grundseite ist 45 cm lang, die Höhe beträgt 30 cm. Wie groß ist die Fläche der Scheibe?"}, "o": {"wert": 1350, "einheit": "cm²"}, "h": "Beim Parallelogramm ist die Fläche Grundseite mal Höhe. Die Höhe steht senkrecht auf der Grundseite.", "w": "A = g · h = 45 · 30 = 1 350 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14376}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Banner hat die Form eines Parallelogramms. Die Grundseite ist 2,4 m lang, die Höhe ist 1,5 m. Der Stoff kostet 8 € je Quadratmeter. Wie viel Euro kostet der Stoff für das Banner?"}, "o": {"wert": 28.8, "einheit": "€"}, "h": "Berechne zuerst die Fläche in m². Dann rechnest du den Preis.", "w": "Fläche: 2,4 · 1,5 = 3,6 m². Preis: 3,6 · 8 = 28,80 €.", "form": "anwenden", "zaehlt": "ja", "r": 14377}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Parallelogramm hat die Fläche 72 cm² und die Seitenlängen 12 cm und 9 cm. Wie groß ist die Summe der beiden zugehörigen Höhen in Zentimetern?"}, "o": {"wert": 14, "einheit": "cm"}, "h": "Die Fläche ist Grundseite mal Höhe. Berechne zu jeder der beiden Seiten die zugehörige Höhe.", "w": "Zur Seite 12 cm gehört die Höhe 72 : 12 = 6 cm. Zur Seite 9 cm gehört die Höhe 72 : 9 = 8 cm. Summe: 6 + 8 = 14 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14378}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Segel ist ein Dreieck mit der Grundseite 9 m und der Höhe 6 m. Wie groß ist die Fläche des Segels?"}, "o": {"wert": 27, "einheit": "m²"}, "h": "Beim Dreieck rechnest du Grundseite mal Höhe und teilst dann durch 2.", "w": "Das Rechteck mit denselben Maßen hat 9 · 6 = 54 m². Das Dreieck ist halb so groß: 54 : 2 = 27 m².", "form": "anwenden", "zaehlt": "ja", "r": 14379}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Wimpelkette hat 8 gleiche Dreiecke aus Stoff. Jedes Dreieck hat die Grundseite 30 cm und die Höhe 40 cm. Wie viele Quadratzentimeter Stoff braucht man für alle Wimpel?"}, "o": {"wert": 4800, "einheit": "cm²"}, "h": "Berechne zuerst die Fläche eines Wimpels. Dann rechnest du mal 8.", "w": "Ein Wimpel: 30 · 40 : 2 = 600 cm². Alle 8 Wimpel: 8 · 600 = 4 800 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14380}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Dreieck hat die Grundseite 14 cm und die Höhe 5 cm. Ein zweites Dreieck hat denselben Flächeninhalt, aber die Grundseite 10 cm. Wie hoch ist das zweite Dreieck?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Das erste Dreieck hat die Fläche 14 · 5 : 2. Für das zweite gilt dieselbe Fläche mit der Grundseite 10 cm.", "w": "Fläche: 14 · 5 : 2 = 35 cm². Zweites Dreieck: 2 · 35 : 10 = 7 cm. Probe: 10 · 7 : 2 = 35.", "form": "anwenden", "zaehlt": "ja", "r": 14381}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Giebelwand eines Schuppens ist ein Trapez. Die parallelen Seiten sind 10 m und 6 m lang, die Höhe ist 3 m. Wie groß ist die Wandfläche?"}, "o": {"wert": 24, "einheit": "m²"}, "h": "Beim Trapez addierst du die parallelen Seiten, multiplizierst mit der Höhe und teilst durch 2.", "w": "(10 + 6) · 3 : 2 = 16 · 3 : 2 = 48 : 2 = 24 m².", "form": "anwenden", "zaehlt": "ja", "r": 14382}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Tischplatte hat die Form eines Trapezes. Die parallelen Seiten sind 1,2 m und 0,8 m lang, der Abstand zwischen ihnen ist 0,5 m. Lack kostet 12 € je Quadratmeter. Wie viel Euro kostet der Lack für die Platte?"}, "o": {"wert": 6, "einheit": "€"}, "h": "Berechne zuerst die Fläche der Platte. Dann rechnest du den Preis.", "w": "Fläche: (1,2 + 0,8) · 0,5 : 2 = 0,5 m². Preis: 0,5 · 12 = 6 €.", "form": "anwenden", "zaehlt": "ja", "r": 14383}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Trapez hat die Fläche 54 cm² und die Höhe 6 cm. Eine der parallelen Seiten ist 11 cm lang. Wie lang ist die andere parallele Seite?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Zweimal die Fläche geteilt durch die Höhe ist die Summe der parallelen Seiten.", "w": "Summe der parallelen Seiten: 2 · 54 : 6 = 18 cm. Die andere Seite: 18 − 11 = 7 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14384}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Beet hat die Form eines Parallelogramms und ist 96 m² groß. Die Seite am Weg ist 12 m lang. Wie breit ist das Beet, gemessen als Abstand senkrecht zum Weg?"}, "o": {"wert": 8, "einheit": "m"}, "h": "Die Fläche ist Grundseite mal Höhe. Teile die Fläche durch die Seite am Weg.", "w": "Die Seite am Weg ist die Grundseite. h = A : g = 96 : 12 = 8 m. Probe: 12 · 8 = 96.", "form": "anwenden", "zaehlt": "ja", "r": 14385}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein dreieckiger Wimpel hat die Fläche 60 cm² und ist 8 cm hoch, gemessen senkrecht zu der Seite, mit der er an der Schnur befestigt ist. An einer Schnur hängen 12 solche Wimpel lückenlos nebeneinander, jeweils mit der Befestigungsseite an der Schnur. Wie lang ist das Schnurstück, an dem alle Wimpel hängen, in Zentimetern?"}, "o": {"wert": 180, "einheit": "cm"}, "h": "Berechne zuerst die Befestigungsseite eines Wimpels: zweimal die Fläche, geteilt durch die Höhe.", "w": "Dreieck: A = g · h : 2. Also g = 2 · 60 : 8 = 15 cm. Für 12 Wimpel: 12 · 15 = 180 cm. Probe: 15 · 8 : 2 = 60.", "form": "anwenden", "zaehlt": "ja", "r": 14386}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rechteck ist 6 cm breit und 12 cm lang. Ein Dreieck hat denselben Flächeninhalt und die Grundseite 16 cm. Wie hoch ist das Dreieck?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Berechne die Fläche des Rechtecks. Beim Dreieck rechnest du dann zweimal die Fläche geteilt durch die Grundseite.", "w": "Rechteck: 6 · 12 = 72 cm². Dreieck: 2 · 72 : 16 = 9 cm. Probe: 16 · 9 : 2 = 72.", "form": "anwenden", "zaehlt": "ja", "r": 14387}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zimmer ist ein Rechteck von 8 m mal 5 m. An einer Seite hat es einen Erker, der ein Quadrat mit 2 m Seitenlänge ist. Wie groß ist die Bodenfläche mit dem Erker?"}, "o": {"wert": 44, "einheit": "m²"}, "h": "Zerlege den Grundriss in ein Rechteck und ein Quadrat. Berechne beide Flächen.", "w": "Rechteck: 8 · 5 = 40 m². Erker: 2 · 2 = 4 m². Zusammen 40 + 4 = 44 m².", "form": "anwenden", "zaehlt": "ja", "r": 14388}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spielfeld ist ein Rechteck von 20 m mal 12 m. In einer Ecke liegt ein Beet in Form eines rechtwinkligen Dreiecks mit den Katheten 6 m und 4 m. Dort darf man nicht spielen. Wie groß ist die Spielfläche?"}, "o": {"wert": 228, "einheit": "m²"}, "h": "Berechne das ganze Rechteck. Ziehe dann die Fläche des Dreiecks ab. Das Dreieck ist halb so groß wie ein Rechteck mit denselben Maßen.", "w": "Rechteck: 20 · 12 = 240 m². Dreieck: 6 · 4 : 2 = 12 m². Spielfläche: 240 − 12 = 228 m².", "form": "anwenden", "zaehlt": "ja", "r": 14389}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Bild ist 40 cm breit und 30 cm hoch. Es hat einen Rahmen, der rundherum 5 cm breit ist. Wie groß ist die Fläche des Rahmens ohne das Bild?"}, "o": {"wert": 800, "einheit": "cm²"}, "h": "Der Rahmen macht das Rechteck auf jeder Seite größer. Berechne das Außenrechteck und ziehe das Bild ab.", "w": "Außen: (40 + 10) · (30 + 10) = 50 · 40 = 2 000 cm². Bild: 40 · 30 = 1 200 cm². Rahmen: 2 000 − 1 200 = 800 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14390}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Geschenk ist ein Quader: 25 cm lang, 12 cm breit und 6 cm hoch. Es wird rundherum in Papier eingepackt, ohne dass sich das Papier überlappt. Wie viele Quadratzentimeter Papier braucht man mindestens?"}, "o": {"wert": 1044, "einheit": "cm²"}, "h": "Ein Quader hat drei Paare gleicher Flächen. Berechne jede Sorte einmal und verdopple die Summe.", "w": "Boden und Deckel: 25 · 12 = 300. Vorder- und Rückseite: 25 · 6 = 150. Die beiden Seiten: 12 · 6 = 72. Summe: 522. Doppelt: 1 044 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14391}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Dachrinne ist 2 m lang. Ihr Querschnitt ist ein Rechteck, 12 cm breit und 8 cm hoch. Die Rinne ist oben offen, ihre beiden Enden sind mit Blech verschlossen. Wie viele Quadratzentimeter Blech werden für Boden, beide Seitenwände und beide Enden gebraucht?"}, "o": {"wert": 5792, "einheit": "cm²"}, "h": "Rechne in cm: 2 m sind 200 cm. Berechne Boden, zwei lange Seitenwände und zwei kleine Endflächen.", "w": "Boden: 12 · 200 = 2 400 cm². Zwei Seitenwände: 2 · 8 · 200 = 3 200 cm². Zwei Enden: 2 · 12 · 8 = 192 cm². Zusammen 2 400 + 3 200 + 192 = 5 792 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14392}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Würfel hat die Oberfläche 54 cm². Zwei solche Würfel werden mit je einer ganzen Fläche zu einem Quader zusammengeklebt. Wie groß ist die Oberfläche des Quaders?"}, "o": {"wert": 90, "einheit": "cm²"}, "h": "Wie groß ist eine Würfelfläche? Beim Zusammenkleben verschwinden zwei Würfelflächen.", "w": "Eine Würfelfläche: 54 : 6 = 9 cm². Beide Würfel: 2 · 54 = 108 cm². Beim Kleben verschwinden 2 · 9 = 18 cm². Oberfläche: 108 − 18 = 90 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14393}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein dreieckiges Blumenbeet hat die Grundseite 10 m und die Höhe 7 m. Ein zweites Beet bekommt dieselbe Grundseite, aber die doppelte Höhe. Wie groß ist die Fläche des zweiten Beets?"}, "o": {"wert": 70, "einheit": "m²"}, "h": "Wie ändert sich die Fläche, wenn die Höhe doppelt so groß wird? Du kannst auch neu rechnen.", "w": "Die neue Höhe ist 14 m. Fläche: 10 · 14 : 2 = 70 m². Die Fläche hat sich verdoppelt (vorher 35 m²).", "form": "anwenden", "zaehlt": "ja", "r": 14394}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rechteck ist 9 cm lang und 6 cm hoch. Ein Parallelogramm hat dieselbe Grundseite 9 cm und dieselbe Höhe 6 cm. Seine schräge Seite ist 8 cm lang. Wie groß ist die Fläche des Parallelogramms?"}, "o": {"wert": 54, "einheit": "cm²"}, "h": "Beim Parallelogramm zählt die Höhe, nicht die schräge Seite. Die Höhe steht senkrecht auf der Grundseite.", "w": "Das Parallelogramm hat dieselbe Grundseite und Höhe wie das Rechteck. Gleiche Fläche: 9 · 6 = 54 cm². Die schräge Seite ist für die Fläche nicht wichtig.", "form": "anwenden", "zaehlt": "ja", "r": 14395}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Kim berechnet ein Trapez mit den parallelen Seiten 8 cm und 4 cm und der Höhe 5 cm so: „8 · 4 · 5 : 2 = 80 cm².“ Um wie viele Quadratzentimeter ist Kims Ergebnis zu groß?"}, "o": {"wert": 50, "einheit": "cm²"}, "h": "Welche Formel gilt beim Trapez? Berechne die richtige Fläche und vergleiche mit Kims 80.", "w": "Richtig: (8 + 4) · 5 : 2 = 30 cm². Kim hat die Seiten malgenommen statt addiert und kommt auf 80 cm². Unterschied: 80 − 30 = 50 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14396}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Papierdrache hat die Diagonalen 60 cm und 40 cm. Wie groß ist die Fläche des Drachens?"}, "o": {"wert": 1200, "einheit": "cm²"}, "h": "Beim Drachen rechnest du: erste Diagonale mal zweite Diagonale, geteilt durch 2.", "w": "A = e · f : 2 = 60 · 40 : 2 = 2 400 : 2 = 1 200 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14397}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Fliese hat die Form einer Raute mit den Diagonalen 18 cm und 10 cm. Zwei gleiche Fliesen liegen nebeneinander. Wie groß ist ihre gesamte Fläche?"}, "o": {"wert": 180, "einheit": "cm²"}, "h": "Berechne zuerst die Fläche einer Fliese. Dann verdoppelst du.", "w": "Eine Fliese: 18 · 10 : 2 = 90 cm². Zwei Fliesen: 2 · 90 = 180 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14398}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Raute hat die Fläche 120 cm², eine ihrer Diagonalen ist 24 cm lang. Die Raute wird in ein Rechteck gezeichnet, dessen Seiten parallel zu den Diagonalen der Raute liegen und das alle vier Ecken der Raute berührt. Wie groß ist der Umfang dieses Rechtecks in Zentimetern?"}, "o": {"wert": 68, "einheit": "cm"}, "h": "Berechne zuerst die andere Diagonale: zweimal die Fläche, geteilt durch die bekannte Diagonale. Die Seiten des Rechtecks sind so lang wie die beiden Diagonalen.", "w": "Fläche der Raute: e · f : 2 = 120, also f = 2 · 120 : 24 = 10 cm. Das Rechteck hat die Seitenlängen e = 24 cm und f = 10 cm. Umfang: 2 · (24 + 10) = 68 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14399}]$auf$::jsonb),
    (94, 'messen.prisma_zylinder', 411, 21, $auf$[{"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Schuppen hat die Form eines Prismas. Die Giebelseite ist ein Rechteck mit aufgesetztem Dreieck: Das Rechteck ist 4 m breit und 2 m hoch, das Dreieck hat die Höhe 1,5 m. Der Schuppen ist 6 m lang. Wie viele Kubikmeter Raum hat der Schuppen?"}, "o": {"wert": 66, "einheit": "m³"}, "h": "Der Schuppen ist ein Prisma. Die Grundfläche ist die Giebelseite aus Rechteck und Dreieck. Berechne zuerst ihre Fläche.", "w": "Rechteck: 4 · 2 = 8 m². Dreieck: 4 · 1,5 : 2 = 3 m². Giebelseite: 11 m². Volumen = Grundfläche · Länge = 11 · 6 = 66 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14412}, {"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Betonprofil ist 2 m lang. Sein Querschnitt hat die Form eines L: Der Fuß ist 30 cm breit und 10 cm hoch. Darauf steht ein Steg, der 10 cm breit und 30 cm hoch ist. Fuß und Steg überlappen sich nicht. Wie viele Kubikdezimeter Beton enthält das Profil?"}, "o": {"wert": 120, "einheit": "dm³"}, "h": "Rechne die Fläche des Querschnitts aus zwei Rechtecken. Achte auf die Einheiten: 1 dm³ = 1 000 cm³.", "w": "Querschnitt: 30 · 10 + 10 · 30 = 600 cm². Länge: 2 m = 200 cm. Volumen: 600 · 200 = 120 000 cm³ = 120 dm³. Probe in dm: Querschnitt 6 dm², Länge 20 dm, 6 · 20 = 120.", "form": "anwenden", "zaehlt": "ja", "r": 14413}, {"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Dreiecksprisma hat als Grundfläche ein Dreieck mit der Grundseite 9 cm und der Höhe 6 cm. Sein Volumen ist genauso groß wie das Volumen eines Würfels mit der Kantenlänge 6 cm. Wie hoch ist das Prisma?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Berechne zuerst das Volumen des Würfels und die Grundfläche des Dreiecks. Danach brauchst du die fehlende Größe des Prismas.", "w": "Würfel: 6³ = 216 cm³. Dreieck: 9 · 6 : 2 = 27 cm². V = G · h, also h = 216 : 27 = 8 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14414}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein gerades Holzprisma wird komplett lackiert. Seine Grundfläche ist ein rechtwinkliges Dreieck mit den Seiten 6 cm, 8 cm und 10 cm. Das Prisma ist 15 cm hoch. Wie viele Quadratzentimeter müssen lackiert werden?"}, "o": {"wert": 408, "einheit": "cm²"}, "h": "Die Oberfläche besteht aus zwei Grundflächen und dem Mantel. Der Mantel ist ein Rechteck: Umfang der Grundfläche mal Höhe.", "w": "Grundfläche: 6 · 8 : 2 = 24 cm². Zwei Grundflächen: 48 cm². Umfang: 6 + 8 + 10 = 24 cm. Mantel: 24 · 15 = 360 cm². O = 48 + 360 = 408 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14415}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Pralinenkarton hat die Form eines geraden Prismas mit einem Quadrat als Grundfläche. Die Grundkante ist 6 cm lang. Die ganze Oberfläche des Kartons ist 192 cm² groß. Wie hoch ist der Karton?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Ziehe von der Oberfläche zuerst die beiden Grundflächen ab. Der Rest ist der Mantel, ein Rechteck mit Umfang mal Höhe.", "w": "Zwei Quadrate: 2 · 36 = 72 cm². Mantel: 192 − 72 = 120 cm². Der Umfang der Grundfläche ist 4 · 6 = 24 cm. Also ist die Höhe 120 : 24 = 5 cm. Probe: 72 + 24 · 5 = 192.", "form": "anwenden", "zaehlt": "ja", "r": 14416}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Blumenkasten ist 100 cm lang. Sein Querschnitt ist ein gleichschenkliges Trapez: unten (Boden) 40 cm breit, oben (offen) 70 cm breit, 20 cm hoch, die schrägen Seiten sind je 25 cm lang. Die obere Seite ist offen, es gibt dort keinen Deckel. Wie viele Quadratzentimeter Blech braucht man für Boden, beide Seitenwände und beide Stirnseiten?"}, "o": {"wert": 11200, "einheit": "cm²"}, "h": "Die Stirnseiten sind die beiden Trapeze. Die Länge 100 cm gilt für Boden und beide schräge Seitenwände. Die Höhe 20 cm ist nicht die Länge der schrägen Seite.", "w": "Ein Trapez: (40 + 70) : 2 · 20 = 1 100 cm², zwei Stirnseiten: 2 200 cm². Boden: 40 · 100 = 4 000 cm². Schräge Seitenwände: 2 · 25 · 100 = 5 000 cm². Zusammen: 2 200 + 4 000 + 5 000 = 11 200 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14417}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Sandkasten hat eine rechteckige Grundfläche von 4 m². Es sind 1,6 m³ Sand eingefüllt, und der Sand liegt überall gleich hoch. Wie hoch liegt der Sand in Zentimetern?"}, "o": {"wert": 40, "einheit": "cm"}, "h": "Die Höhe ist das Volumen geteilt durch die Grundfläche. Am Ende musst du in Zentimeter umrechnen.", "w": "h = V : G = 1,6 m³ : 4 m² = 0,4 m = 40 cm. Probe: 4 m² · 0,4 m = 1,6 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14418}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Becken hat die Form eines Prismas. Seine Grundfläche ist ein Trapez mit den parallelen Seiten 40 cm und 60 cm und dem Abstand 25 cm. In das Becken passen genau 25 Liter. Wie hoch ist das Prisma in Zentimetern?"}, "o": {"wert": 20, "einheit": "cm"}, "h": "Berechne zuerst die Trapezfläche. Rechne die Liter in cm³ um: 1 Liter = 1 000 cm³.", "w": "Grundfläche: (40 + 60) : 2 · 25 = 1 250 cm². Volumen: 25 l = 25 000 cm³. Höhe: 25 000 : 1 250 = 20 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14419}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Quader-Gefäß mit der Grundfläche 20 cm mal 15 cm steht Saft 12 cm hoch. Der ganze Saft wird in ein Dreiecksprisma-Gefäß gegossen, das 40 cm hoch ist. Seine Grundfläche ist ein Dreieck mit der Grundseite 24 cm und der Höhe 10 cm. Wie hoch steht der Saft im zweiten Gefäß in Zentimetern?"}, "o": {"wert": 30, "einheit": "cm"}, "h": "Das Volumen des Safts bleibt beim Umgießen gleich. Berechne die Grundfläche des zweiten Gefäßes.", "w": "Volumen: 20 · 15 · 12 = 3 600 cm³. Grundfläche des Dreiecks: 24 · 10 : 2 = 120 cm². Füllhöhe: 3 600 : 120 = 30 cm. Das ist weniger als die Gefäßhöhe 40 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14420}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Baumstamm hat die Form eines Zylinders mit dem Durchmesser 40 cm und der Länge 3 m. Wie viele Kubikdezimeter Holz sind das? Rechne mit π ≈ 3,14."}, "o": {"wert": 376.8, "einheit": "dm³"}, "h": "Rechne alle Maße in dm um. Aus dem Durchmesser bekommst du den Radius.", "w": "r = 40 cm : 2 = 20 cm = 2 dm, Länge = 3 m = 30 dm. V = π · r² · h ≈ 3,14 · 4 · 30 = 376,8 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14421}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Betonrohr ist 2 m lang. Der äußere Radius ist 30 cm, der innere Radius ist 20 cm. Wie viele Kubikdezimeter Beton enthält das Rohr? Rechne mit π ≈ 3,14."}, "o": {"wert": 314, "einheit": "dm³"}, "h": "Das Rohr ist ein großer Zylinder, aus dem ein kleiner Zylinder herausgeschnitten ist. Rechne in dm.", "w": "Rechne in dm: R = 3 dm, r = 2 dm, Länge 20 dm. V = (π · R² − π · r²) · h = 3,14 · (9 − 4) · 20 = 3,14 · 100 = 314 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14422}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Durch ein Rohr mit dem Innenradius 2 cm fließt Wasser gleichmäßig: Der Wasserfaden legt in jeder Sekunde 5 cm zurück. Wie viele Kubikzentimeter Wasser fließen in einer Minute durch das Rohr? Rechne mit π ≈ 3,14."}, "o": {"wert": 3768, "einheit": "cm³"}, "h": "Das Wasser einer Sekunde ist ein Zylinder mit dem Radius 2 cm und der Höhe 5 cm. Wie viele Sekunden hat eine Minute?", "w": "In einer Sekunde fließt ein Zylinder mit r = 2 cm und h = 5 cm: 3,14 · 2² · 5 = 62,8 cm³. In einer Minute (60 Sekunden): 60 · 62,8 = 3 768 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14423}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein zylinderförmiger Blecheimer ist oben offen. Er hat den Radius 15 cm und die Höhe 30 cm. Wie viele Quadratzentimeter Blech braucht man für Boden und Mantel? Rechne mit π ≈ 3,14."}, "o": {"wert": 3532.5, "einheit": "cm²"}, "h": "Der Eimer hat keinen Deckel. Der Mantel ist ein Rechteck: Kreisumfang mal Höhe.", "w": "Boden: π · r² ≈ 3,14 · 225 = 706,5 cm². Mantel: 2 · π · r · h ≈ 2 · 3,14 · 15 · 30 = 2 826 cm². Zusammen: 706,5 + 2 826 = 3 532,5 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14424}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Wassertank ist ein geschlossener Zylinder mit dem Durchmesser 2 m und der Höhe 3 m. Er wird außen zweimal gestrichen. Ein Liter Farbe reicht für einen Anstrich von 4 m². Wie viele Liter Farbe braucht man für die beiden Anstriche? Rechne mit π ≈ 3,14."}, "o": {"wert": 12.56, "einheit": "l"}, "h": "Berechne zuerst die ganze Oberfläche (Boden, Deckel, Mantel) in m². Der Radius ist die Hälfte des Durchmessers.", "w": "r = 1 m. Boden und Deckel: 2 · 3,14 · 1 = 6,28 m². Mantel: 2 · 3,14 · 1 · 3 = 18,84 m². Oberfläche: 25,12 m². Zwei Anstriche: 50,24 m². Farbe: 50,24 : 4 = 12,56 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14425}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine geschlossene Blechdose hat die Form eines Zylinders mit dem Radius 4 cm. Für die ganze Dose (Boden, Deckel und Mantel) werden 326,56 cm² Blech gebraucht. Rechne mit π ≈ 3,14. Wie hoch ist die Dose in Zentimetern?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Ziehe zuerst Boden und Deckel ab. Der Rest ist der Mantel: Umfang mal Höhe.", "w": "Boden und Deckel: 2 · 3,14 · 16 = 100,48 cm². Mantel: 326,56 − 100,48 = 226,08 cm². Der Kreisumfang ist 2 · 3,14 · 4 = 25,12 cm. Höhe: 226,08 : 25,12 = 9 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14426}, {"l": "sach", "t": "sach", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein zylinderförmiger Wassertank hat den Durchmesser 2 m und ist 3 m hoch. Wie viele Liter fasst er? Rechne mit π ≈ 3,14. Es gilt 1 m³ = 1 000 Liter."}, "o": {"wert": 9420, "einheit": "l"}, "h": "Aus dem Durchmesser bekommst du den Radius. Rechne zuerst das Volumen in m³ aus.", "w": "r = 1 m. V = 3,14 · 1² · 3 = 9,42 m³. Das sind 9,42 · 1 000 = 9 420 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14427}, {"l": "sach", "t": "sach", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Lagerhalle ist 20 m lang. Ihr Querschnitt besteht aus einem Rechteck (10 m breit, 4 m hoch) und einem Dreieck als Dach darüber (10 m breit, 3 m hoch). Wie groß ist der umbaute Raum der Halle in m³?"}, "o": {"wert": 1100, "einheit": "m³"}, "h": "Die Halle ist ein Prisma. Bestimme erst die Fläche des Querschnitts aus Rechteck und Dreieck.", "w": "Querschnitt: Rechteck 10 · 4 = 40 m², Dreieck 10 · 3 : 2 = 15 m². Zusammen 55 m². Volumen: 55 · 20 = 1 100 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14428}, {"l": "sach", "t": "sach", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein zylinderförmiges Gefäß hat den Radius 20 cm. Es ist 50 cm hoch mit Wasser gefüllt. Das ganze Wasser wird in einen sehr hohen quaderförmigen Behälter mit der Grundfläche 40 cm mal 25 cm umgefüllt. Wie viele Zentimeter hoch steht das Wasser dann im Quader? Rechne mit π ≈ 3,14."}, "o": {"wert": 62.8, "einheit": "cm"}, "h": "Berechne zuerst das Volumen des Wassers im Zylinder. Beim Quader teilst du das Volumen durch die Grundfläche.", "w": "Wasser im Zylinder: 3,14 · 400 · 50 = 62 800 cm³. Grundfläche des Quaders: 40 · 25 = 1 000 cm². Höhe: 62 800 : 1 000 = 62,8 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14429}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Becher A fasst 120 ml und ist ein Zylinder. Becher B ist genauso hoch, hat aber den doppelten Radius. Wie viele Milliliter fasst Becher B?"}, "o": {"wert": 480, "einheit": "ml"}, "h": "Die Höhe bleibt gleich. Wie ändert sich die Grundfläche π · r², wenn der Radius doppelt so groß wird?", "w": "Mit dem doppelten Radius wird r² viermal so groß, also auch die Grundfläche. Bei gleicher Höhe ist das Volumen viermal so groß: 4 · 120 = 480 ml.", "form": "anwenden", "zaehlt": "ja", "r": 14430}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Dose A ist ein Zylinder mit dem Radius 4 cm und der Höhe 6 cm. Dose B ist ein Zylinder mit dem Radius 6 cm und der Höhe 4 cm. Das Volumen von Dose B ist um n · π cm³ größer als das von Dose A. Welche Zahl ist n?"}, "o": {"wert": 48}, "h": "Berechne beide Volumina als Vielfache von π. Beachte, welche Größe quadriert wird.", "w": "A: π · 4² · 6 = 96π cm³. B: π · 6² · 4 = 144π cm³. Unterschied: 144π − 96π = 48π. Also ist n = 48. Die Dose mit dem größeren Radius ist größer, obwohl sie niedriger ist.", "form": "anwenden", "zaehlt": "ja", "r": 14431}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "zahl", "f": {"text": "Ein Stapel aus 10 runden Pappscheiben steht gerade. Jede Scheibe hat den Radius 3 cm und ist 1 cm dick. Dann wird der Stapel seitlich verschoben, sodass er schief steht. Dabei ändert sich keine Scheibe. Wie groß ist das Volumen des schiefen Stapels in cm³? Rechne mit π ≈ 3,14."}, "o": {"wert": 282.6, "einheit": "cm³"}, "h": "Jede Scheibe hat dasselbe Volumen wie vorher. Wie viele Scheiben gibt es?", "w": "Das Volumen einer Scheibe ist 3,14 · 3² · 1 = 28,26 cm³. Beim Verschieben ändert sich keine Scheibe, also bleibt auch die Summe gleich: 10 · 28,26 = 282,6 cm³. Ein schiefer Zylinder hat dasselbe Volumen wie der gerade mit gleicher Grundfläche und Höhe.", "form": "anwenden", "zaehlt": "ja", "r": 14432}]$auf$::jsonb),
    (95, 'messen.volumen', 369, 21, $auf$[{"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schachtel ist innen 5 cm lang, 4 cm breit und 3 cm hoch. Kim füllt sie ganz mit Würfeln, die 1 cm Kante haben. Wie viele Würfel passen hinein?"}, "o": {"wert": 60}, "h": "Wie viele Würfel liegen in der untersten Schicht? Wie viele Schichten passen übereinander?", "w": "Eine Schicht hat 5 · 4 = 20 Würfel. Es passen 3 Schichten hinein: 20 · 3 = 60 Würfel.", "form": "anwenden", "zaehlt": "ja", "r": 14370}, {"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Aus Würfeln mit 1 cm Kante baut Sam ein Raumkreuz: In der Mitte liegt ein Würfel. An jeder der sechs Seiten dieses Würfels schließt sich ein Arm aus 3 Würfeln an, die in einer geraden Reihe nach außen liegen. Wie viele Würfel braucht Sam?"}, "o": {"wert": 19, "einheit": "Würfel"}, "h": "Wie viele Arme gibt es, und wie viele Würfel hat jeder Arm? Vergiss den Würfel in der Mitte nicht.", "w": "Es gibt 6 Arme mit je 3 Würfeln: 6 · 3 = 18 Würfel. Dazu kommt der Würfel in der Mitte: 18 + 1 = 19 Würfel.", "form": "anwenden", "zaehlt": "ja", "r": 14371}, {"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Quader besteht aus 5 · 4 · 3 kleinen Würfeln. Er wird außen ganz angemalt, auch unten. Wie viele kleine Würfel haben dann keine angemalte Fläche?"}, "o": {"wert": 6}, "h": "Welche kleinen Würfel liegen ganz innen? Wie viele Schichten bleiben in jeder Richtung ohne die äußeren?", "w": "Außen liegen in jeder Richtung 2 Schichten. Es bleiben 5 − 2 = 3, 4 − 2 = 2 und 3 − 2 = 1 Würfel. Innen liegen 3 · 2 · 1 = 6 kleine Würfel.", "form": "anwenden", "zaehlt": "ja", "r": 14372}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Umzugskarton ist 40 cm lang, 25 cm breit und 20 cm hoch. Wie groß ist sein Volumen?"}, "o": {"wert": 20000, "einheit": "cm³"}, "h": "Das Volumen eines Quaders ist Länge mal Breite mal Höhe.", "w": "Grundfläche: 40 · 25 = 1 000 cm². Volumen: 1 000 · 20 = 20 000 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14373}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Schwimmbecken ist 8 m lang und 4,5 m breit. Das Wasser steht 1,5 m hoch. Wie viel Kubikmeter Wasser sind im Becken?"}, "o": {"wert": 54, "einheit": "m³"}, "h": "Das Wasser bildet einen Quader. Seine Höhe ist die Wasserhöhe.", "w": "Grundfläche: 8 · 4,5 = 36 m². Volumen: 36 · 1,5 = 54 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14374}, {"l": "quader", "t": "quader", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Aus einem Wachsblock (12 cm lang, 6 cm breit, 5 cm hoch) wird ohne Verlust ein neuer Quader mit quadratischer Grundfläche gegossen. Die Grundfläche hat die Seitenlänge 6 cm. Wie hoch wird der neue Quader in Zentimetern?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Das Volumen bleibt gleich. Berechne zuerst das Volumen des Wachsblocks. Wie groß ist die neue Grundfläche?", "w": "Wachsblock: 12 · 6 · 5 = 360 cm³. Neue Grundfläche: 6 · 6 = 36 cm². Höhe: 360 : 36 = 10 cm. Probe: 36 · 10 = 360.", "form": "anwenden", "zaehlt": "ja", "r": 14375}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Regenwassertank fasst 3,6 m³. Wie viele Kubikdezimeter sind das?"}, "o": {"wert": 3600, "einheit": "dm³"}, "h": "Bei Volumen ist jeder Schritt zur nächsten Einheit mal oder durch 1 000. Von m³ nach dm³ ist es ein Schritt.", "w": "1 m³ = 1 000 dm³. Also 3,6 m³ = 3,6 · 1 000 = 3 600 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14376}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Sam hat 0,8 m³ Sand. Eine Schubkarre fasst 40 dm³. Wie viele volle Schubkarren ergibt der Sand?"}, "o": {"wert": 20}, "h": "Rechne zuerst die Kubikmeter in Kubikdezimeter um. Dann teilst du.", "w": "0,8 m³ = 800 dm³. Dann 800 : 40 = 20 Schubkarren.", "form": "anwenden", "zaehlt": "ja", "r": 14377}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Tank A fasst 0,004 m³, Tank B fasst 3,2 dm³ und Tank C fasst 2 500 cm³. Um wie viele Kubikzentimeter ist der größte Tank größer als der kleinste?"}, "o": {"wert": 1500, "einheit": "cm³"}, "h": "Schreibe alle drei Angaben in derselben Einheit, am besten in cm³. Dann suchst du den größten und den kleinsten Tank.", "w": "0,004 m³ = 4 000 cm³ und 3,2 dm³ = 3 200 cm³. Tank C hat 2 500 cm³. Der größte Tank ist A, der kleinste ist C: 4 000 − 2 500 = 1 500 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14378}, {"l": "liter", "t": "liter", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Regentonne ist innen 50 cm lang, 40 cm breit und 60 cm hoch. Wie viele Liter passen hinein, wenn sie ganz voll ist?"}, "o": {"wert": 120, "einheit": "l"}, "h": "Berechne das Volumen in cm³. Ein Liter sind 1 000 cm³.", "w": "Volumen: 50 · 40 · 60 = 120 000 cm³. Mit 1 l = 1 000 cm³ sind das 120 000 : 1 000 = 120 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14379}, {"l": "liter", "t": "liter", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim füllt 6 Liter Saft aus einem Kanister in Becher. In jeden Becher kommen 250 ml. Wie viele Becher werden voll?"}, "o": {"wert": 24}, "h": "Rechne die Liter in Milliliter um. Dann teilst du.", "w": "6 l = 6 000 ml. 6 000 : 250 = 24 Becher.", "form": "anwenden", "zaehlt": "ja", "r": 14380}, {"l": "liter", "t": "liter", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Becken ist 3 m lang, 2 m breit und 1,2 m hoch. Es ist leer. Pro Minute fließen 40 Liter hinein. Nach wie vielen Minuten steht das Wasser 0,5 m hoch?"}, "o": {"wert": 75, "einheit": "Minuten"}, "h": "Wie viele Kubikmeter Wasser sind bei 0,5 m Höhe im Becken? Rechne in Liter um.", "w": "Bei 0,5 m Höhe sind es 3 · 2 · 0,5 = 3 m³ = 3 000 Liter. 3 000 : 40 = 75 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 14381}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quaderförmiger Karton fasst 3 600 cm³. Er ist 20 cm lang und 15 cm breit. Wie hoch ist er?"}, "o": {"wert": 12, "einheit": "cm"}, "h": "Teile das Volumen durch die Grundfläche.", "w": "Grundfläche: 20 · 15 = 300 cm². Höhe: 3 600 : 300 = 12 cm. Probe: 300 · 12 = 3 600.", "form": "anwenden", "zaehlt": "ja", "r": 14382}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Sandkasten ist 2 m lang und 1,5 m breit. Hinein kommen 0,6 m³ Sand, glatt verteilt. Wie viele Zentimeter hoch liegt der Sand?"}, "o": {"wert": 20, "einheit": "cm"}, "h": "Teile das Volumen durch die Grundfläche. Das Ergebnis ist zuerst in Metern.", "w": "Grundfläche: 2 · 1,5 = 3 m². Höhe: 0,6 : 3 = 0,2 m = 20 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14383}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine quaderförmige Dose ist innen 12 cm lang und 5 cm breit. Sie soll 1,5 Liter fassen. Damit der Deckel passt, muss oben 2 cm Platz bleiben. Wie hoch muss die Dose innen mindestens sein?"}, "o": {"wert": 27, "einheit": "cm"}, "h": "1 Liter sind 1 000 cm³. Berechne zuerst die Höhe für 1,5 Liter. Was kommt wegen des Deckels dazu?", "w": "1,5 l = 1 500 cm³. Grundfläche: 12 · 5 = 60 cm². Höhe für den Inhalt: 1 500 : 60 = 25 cm. Dazu 2 cm Platz: 27 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14384}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Sockel besteht aus zwei Teilen. Unten liegt ein Quader mit 3 dm Länge, 2 dm Breite und 1 dm Höhe. Obendrauf steht ein Würfel mit 2 dm Kante. Wie groß ist das Volumen des ganzen Sockels?"}, "o": {"wert": 14, "einheit": "dm³"}, "h": "Berechne das Volumen jedes Teils einzeln. Dann addierst du.", "w": "Quader: 3 · 2 · 1 = 6 dm³. Würfel: 2 · 2 · 2 = 8 dm³. Zusammen 6 + 8 = 14 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14385}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Holzquader ist 10 cm lang, 8 cm breit und 6 cm hoch. Durch die Mitte wird von oben nach unten ein Loch mit quadratischem Querschnitt gebohrt: 3 cm mal 3 cm, ganz durch. Wie groß ist das Volumen des Holzes, das übrig bleibt?"}, "o": {"wert": 426, "einheit": "cm³"}, "h": "Berechne das Volumen des ganzen Quaders und das des Lochs. Das Loch geht über die ganze Höhe.", "w": "Ganzer Quader: 10 · 8 · 6 = 480 cm³. Loch: 3 · 3 · 6 = 54 cm³. Rest: 480 − 54 = 426 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14386}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein offener Betontrog hat außen die Maße 5 m Länge, 3 m Breite und 2 m Höhe. Innen ist er ausgehöhlt: 4 m lang, 2 m breit und 1,5 m tief. Wie viele Kubikmeter Beton stecken in dem Trog?"}, "o": {"wert": 18, "einheit": "m³"}, "h": "Der Trog ist ein großer Quader, aus dem der Hohlraum fehlt. Berechne beide Volumen.", "w": "Außen: 5 · 3 · 2 = 30 m³. Hohlraum: 4 · 2 · 1,5 = 12 m³. Beton: 30 − 12 = 18 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14387}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Regal ist 1,9 m hoch, 0,4 m breit und 0,3 m tief. Zum Überschlag rundet Kim nur die Höhe auf 2 m. Wie viele Kubikmeter ergibt der Überschlag?"}, "o": {"wert": 0.24, "einheit": "m³"}, "h": "Beim Überschlag rechnest du mit der gerundeten Höhe und den beiden anderen Kanten: Länge mal Breite mal Höhe.", "w": "Mit der gerundeten Höhe: 2 · 0,4 · 0,3 = 0,24 m³. Das genaue Volumen (0,228 m³) liegt nahe dabei.", "form": "anwenden", "zaehlt": "ja", "r": 14388}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader hat das Volumen 20 cm³. Seine Länge und seine Breite werden jeweils verdoppelt. Die Höhe bleibt gleich. Wie groß ist jetzt das Volumen?"}, "o": {"wert": 80, "einheit": "cm³"}, "h": "Wie oft passt der alte Quader in den neuen? Die Länge wird doppelt so groß und die Breite auch.", "w": "Der Faktor 2 wirkt zweimal: 2 · 2 = 4. Das neue Volumen ist 20 · 4 = 80 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14389}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Ein Quader ist 2 cm lang, 3 cm breit und 4 cm hoch. Kim sagt: „Halbiere ich alle drei Kanten, wird auch das Volumen halbiert.“ Kim rechnet deshalb mit 12 cm³. Um wie viele Kubikzentimeter ist Kims Wert zu groß?"}, "o": {"wert": 9, "einheit": "cm³"}, "h": "Das Volumen des Quaders ist 24 cm³. Halbierst du jede der drei Kanten, wirkt der Faktor ein halbes dreimal.", "w": "Der Faktor 1/2 wirkt dreimal: 24 · 1/8 = 3 cm³. Kims Wert 12 cm³ ist 12 − 3 = 9 cm³ zu groß.", "form": "anwenden", "zaehlt": "ja", "r": 14390}]$auf$::jsonb),
    (112, 'terme.potenzgesetze_ganzzahlig', 112, 15, $auf$[{"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Menge eines Wirkstoffs im Blut halbiert sich jede Stunde. Zu Beginn sind es 160 mg. Nach n Stunden sind es 160 · 2⁻ⁿ mg. Wie viel Milligramm sind es nach 5 Stunden?"}, "o": {"wert": 5, "einheit": "mg"}, "h": "2⁻ⁿ bedeutet: n-mal halbieren. Schreibe 2⁻⁵ als Bruch.", "w": "2⁻⁵ ist der Bruch 1/2⁵ = 1/32. Also sind es nach 5 Stunden 160 · 1/32 = 160 : 32 = 5 mg. Probe: 160, 80, 40, 20, 10, 5 – fünfmal halbiert.", "form": "anwenden", "zaehlt": "ja", "r": 14113}, {"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim schneidet von einem 1 m langen Seil zuerst die Hälfte ab. Vom Rest schneidet Kim wieder die Hälfte ab, und danach noch einmal die Hälfte vom neuen Rest. Die drei abgeschnittenen Stücke sind 2⁻¹ m, 2⁻² m und 2⁻³ m lang. Wie viele Meter sind die drei Stücke zusammen lang? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 0.875, "einheit": "m"}, "h": "Schreibe jedes Stück als Bruch. Was bedeutet 2⁻³?", "w": "2⁻¹ = 1/2, 2⁻² = 1/4, 2⁻³ = 1/8. Zusammen: 1/2 + 1/4 + 1/8 = 4/8 + 2/8 + 1/8 = 7/8 = 0,875 m. Probe: Das Seil hat noch 1/8 m übrig, und 1 − 1/8 = 7/8.", "form": "anwenden", "zaehlt": "ja", "r": 14114}, {"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Substanz zerfällt so, dass ihre Menge jede Stunde auf die Hälfte sinkt. Jetzt sind 3 g da. Die Formel M(t) = 3 · 2⁻ᵗ gibt die Menge in Gramm t Stunden nach jetzt an. Für t = −2 liefert die Formel die Menge von vor 2 Stunden. Wie viel Gramm waren es vor 2 Stunden?"}, "o": {"wert": 12, "einheit": "g"}, "h": "Setze t = −2 ein. Was bedeutet 2 hoch (−(−2))? Was passiert mit der Menge, wenn man zwei Stunden zurückgeht?", "w": "Für t = −2 ist 2⁻ᵗ = 2²= 4. Also M(−2) = 3 · 4 = 12 g. Das passt: Von vor 2 Stunden bis jetzt wurde die Menge zweimal halbiert, 12 → 6 → 3.", "form": "anwenden", "zaehlt": "ja", "r": 14115}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Staubkorn ist 10⁻⁵ m dick. Ein Blatt Papier ist 10⁻⁴ m dick. 30 Blätter liegen aufeinander. Wie viele Staubkörner müsste man aufeinanderlegen, um dieselbe Dicke zu erreichen?"}, "o": {"wert": 300, "einheit": "Staubkörner"}, "h": "Wie viele Staubkörner sind so dick wie ein Blatt? Teile 10⁻⁴ durch 10⁻⁵.", "w": "Ein Blatt: 10⁻⁴ : 10⁻⁵. Man zieht die Hochzahlen ab: −4 − (−5) = −4 + 5 = 1. Also 10¹ = 10 Staubkörner. Bei 30 Blättern sind es 30 · 10 = 300 Staubkörner.", "form": "anwenden", "zaehlt": "ja", "r": 14116}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Zelle ist 5 · 10⁻⁶ m breit. Auf einem Objektträger liegt eine lückenlose Reihe solcher Zellen. Die Reihe ist 2 · 10⁻³ m lang. Wie viele Zellen sind es?"}, "o": {"wert": 400, "einheit": "Zellen"}, "h": "Teile die Länge der Reihe durch die Breite einer Zelle. Rechne die Zahlen und die Zehnerpotenzen getrennt.", "w": "Anzahl = (2 · 10⁻³) : (5 · 10⁻⁶). Zahlen: 2 : 5 = 0,4. Hochzahlen abziehen: −3 − (−6) = −3 + 6 = 3. Also 0,4 · 10³ = 400 Zellen.", "form": "anwenden", "zaehlt": "ja", "r": 14117}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Kristall wiegt 10⁻³ g. Ein Päckchen enthält 10ᵏ solche Kristalle und wiegt zusammen 10² g. Welche ganze Zahl ist k?"}, "o": {"wert": 5}, "h": "Gesamtgewicht = Gewicht eines Kristalls mal Anzahl. Die Hochzahlen der Zehnerpotenzen werden dabei addiert.", "w": "Es gilt 10⁻³ · 10ᵏ = 10², also 10⁻³⁺ᵏ = 10². Daraus folgt −3 + k = 2 und k = 5. Probe: 10⁻³ · 10⁵ = 10² = 100 g.", "form": "anwenden", "zaehlt": "ja", "r": 14118}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Pixel auf einem Bildschirm hat die Seitenlänge 2⁻³ mm. Wie groß ist die Fläche des Pixels in mm²? Gib sie als Dezimalzahl an."}, "o": {"wert": 0.015625, "einheit": "mm²"}, "h": "Fläche eines Quadrats = Seite mal Seite. Welche Hochzahl hat (2⁻³)²?", "w": "A = (2⁻³)². Man multipliziert die Hochzahlen: (−3) · 2 = −6. Also A = 2⁻⁶ = 1/64 = 0,015625 mm². Probe: 1/8 · 1/8 = 1/64.", "form": "anwenden", "zaehlt": "ja", "r": 14119}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein würfelförmiger Behälter hat die Kantenlänge 5⁻¹ m. Wie viele Liter fasst er? Es gilt 1 m³ = 1 000 Liter."}, "o": {"wert": 8, "einheit": "l"}, "h": "Das Volumen eines Würfels ist Kante mal Kante mal Kante. Rechne zuerst in m³, dann in Liter.", "w": "V = (5⁻¹)³ m³ = 5⁻³ m³ = 1/125 m³. Das sind 1 000 : 125 = 8 Liter. Probe: Die Kante ist 0,2 m = 2 dm, und 2 dm · 2 dm · 2 dm = 8 dm³ = 8 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14120}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Alex hat ein Zahlenrätsel gestellt: Es gibt genau eine ganze Zahl k, für die (3⁻²)ᵏ · 3⁷ = 3 gilt. Welche Zahl ist k?"}, "o": {"wert": 3}, "h": "Fasse die linke Seite zu einer einzigen Potenz von 3 zusammen. Welche Hochzahl hat (3⁻²)ᵏ?", "w": "Bei (3⁻²)ᵏ multipliziert man die Hochzahlen: Die Hochzahl ist −2 · k. Beim Malnehmen mit 3⁷ addiert man die Hochzahlen: −2 · k + 7. Das soll 1 sein (denn 3 = 3¹). Also −2 · k + 7 = 1, 2 · k = 6 und k = 3. Probe: (3⁻²)³ · 3⁷ = 3⁻⁶ · 3⁷ = 3.", "form": "anwenden", "zaehlt": "ja", "r": 14121}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim vereinfacht den Term 10x⁴ : (4x⁷) und setzt danach x = 2 ein. Welchen Wert erhält Kim? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 0.3125}, "h": "Vereinfache zuerst: Zahlen für sich, Potenzen von x für sich. Setze x = 2 zuletzt ein.", "w": "10x⁴ : (4x⁷) = (10 : 4) · x⁴⁻⁷ = 2,5 · x⁻³ = 2,5/x³. Für x = 2: 2,5/8 = 0,3125. Probe ohne Vereinfachen: 10 · 16 = 160 und 4 · 128 = 512, und 160 : 512 = 0,3125.", "form": "anwenden", "zaehlt": "ja", "r": 14122}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Preis für ein Bastelset (in Euro) wird durch K(x) = 20x⁵ : (4x⁷) beschrieben. Dabei ist x die Zahl der gekauften Hunderterpackungen. Wie viel Euro kostet ein Set bei x = 5?"}, "o": {"wert": 0.2, "einheit": "€"}, "h": "Vereinfache K(x) zuerst: Zahlen für sich, Potenzen von x für sich. Danach setzt du x = 5 ein.", "w": "K(x) = (20 : 4) · x⁵⁻⁷ = 5x⁻² = 5/x². Für x = 5: 5/25 = 0,2. Ein Set kostet 0,20 €.", "form": "anwenden", "zaehlt": "ja", "r": 14123}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Alex vereinfacht den Term (6x⁻³ · x⁵) : (3x⁻¹) zu einem Produkt c · xⁿ. Danach setzt er x = 2 ein. Welchen Wert erhält er?"}, "o": {"wert": 16}, "h": "Fasse Zähler und Nenner getrennt zusammen. Beim Teilen durch x⁻¹ wird die Hochzahl −1 abgezogen.", "w": "Zähler: 6x⁻³ · x⁵. Hochzahlen addieren: −3 + 5 = 2, also 6x². Dann 6x² : (3x⁻¹): Zahlen 6 : 3 = 2, Hochzahlen abziehen: 2 − (−1) = 3. Das ergibt 2x³. Für x = 2: 2 · 8 = 16. Probe mit dem Ausgangsterm: 6 · 2⁻³ · 2⁵ = 24 und 3 · 2⁻¹ = 1,5, und 24 : 1,5 = 16.", "form": "anwenden", "zaehlt": "ja", "r": 14124}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim behauptet: 4⁻¹ + 4⁻¹ = 4⁻². Mit einer Zahlenprobe kann man das prüfen. Um wie viel ist die linke Seite größer als die rechte Seite? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 0.4375}, "h": "Berechne beide Seiten einzeln als Bruch oder als Dezimalzahl. Dann bildest du die Differenz.", "w": "Linke Seite: 4⁻¹ + 4⁻¹ = 1/4 + 1/4 = 1/2 = 0,5. Rechte Seite: 4⁻² = 1/16 = 0,0625. Die Behauptung stimmt nicht. Unterschied: 0,5 − 0,0625 = 0,4375. Beim Addieren gleicher Potenzen werden die Hochzahlen nicht addiert.", "form": "anwenden", "zaehlt": "ja", "r": 14125}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim berechnet 10⁻² · 10⁵ : 10⁻¹ und erhält 100. Die Zahlenprobe zeigt: Das stimmt nicht. Wie groß ist der richtige Wert?"}, "o": {"wert": 10000}, "h": "Kim hat beim Teilen durch 10⁻¹ vermutlich die Hochzahl falsch abgezogen. Rechne mit Brüchen nach.", "w": "Beim Malnehmen addiert man: −2 + 5 = 3, also 10³. Beim Teilen durch 10⁻¹ zieht man −1 ab: 3 − (−1) = 4, also 10⁴ = 10 000. Probe mit Zahlen: 0,01 · 100 000 = 1 000, und 1 000 : 0,1 = 10 000.", "form": "anwenden", "zaehlt": "ja", "r": 14126}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Kim behauptet für a ≠ 0: (a⁻²)³ · a⁵ : (a⁻¹)⁴ = a⁴. Kims Rechnung stimmt nicht. Wie groß ist die linke Seite für a = 2, wenn man richtig rechnet?"}, "o": {"wert": 8}, "h": "Fasse zuerst jeden Teil zu einer Potenz von a zusammen. Dann rechnest du mit den Hochzahlen von links nach rechts.", "w": "(a⁻²)³ = a⁻⁶. Dann a⁻⁶ · a⁵ = a⁻¹. Außerdem (a⁻¹)⁴ = a⁻⁴. Beim Teilen zieht man die Hochzahlen ab: −1 − (−4) = −1 + 4 = 3. Die linke Seite ist a³, für a = 2 also 2³ = 8. Probe: 2⁻⁶ · 2⁵ = 1/2 und 2⁻⁴ = 1/16, und 1/2 : 1/16 = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14127}]$auf$::jsonb),
    (304, 'groessen.proportional_teil2', 573, 9, $auf$[{"l": "erkennen", "t": "begriff", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Aufzug legt in 4 Sekunden 10 m zurück. Kim rechnet damit, dass er in der gleichen Weise weiterfährt. Wie viele Meter fährt er in 10 Sekunden?"}, "o": {"wert": 25, "einheit": "m"}, "h": "Proportional heißt: Zur doppelten Zeit gehört die doppelte Strecke. Wie weit fährt der Aufzug in 1 Sekunde?", "w": "In 1 Sekunde fährt er 10 : 4 = 2,5 m. In 10 Sekunden fährt er 10 · 2,5 = 25 m. Probe: In 8 Sekunden wären es 20 m, dazu noch 2 Sekunden mit 5 m.", "form": "anwenden", "zaehlt": "ja", "r": 14574}, {"l": "erkennen", "t": "begriff", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Bäckerei A: 6 Brötchen kosten 2,40 €, jedes Brötchen kostet gleich viel. Bäckerei B: 1 € Tütengebühr und dazu 0,30 € für jedes Brötchen. Bei einer der beiden Bäckereien ist die Zuordnung Anzahl → Preis proportional. Wie viel Euro kosten dort 12 Brötchen?"}, "o": {"wert": 4.8, "einheit": "€"}, "h": "Bei einer proportionalen Zuordnung gehört zu 0 Brötchen der Preis 0. Bei welcher Bäckerei ist das so?", "w": "Bei Bäckerei B kostet schon die Tüte 1 €, auch bei 0 Brötchen: Das ist nicht proportional. Bei Bäckerei A kostet ein Brötchen 2,40 : 6 = 0,40 €. 12 Brötchen kosten 12 · 0,40 = 4,80 €. Das ist das Doppelte von 2,40 €.", "form": "anwenden", "zaehlt": "ja", "r": 14575}, {"l": "erkennen", "t": "begriff", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Sam behauptet: „Die Zuordnung Alter → Körpergröße ist proportional.“ Mit 8 Jahren war Sam 128 cm groß, mit 12 Jahren ist Sam 152 cm groß. Sam rechnet vom Wert bei 8 Jahren proportional weiter und sagt voraus, wie groß er mit 20 Jahren wäre. Um wie viele Zentimeter ist diese Vorhersage größer als eine realistische Größe von 180 cm?"}, "o": {"wert": 140, "einheit": "cm"}, "h": "Berechne zuerst, wie viele Zentimeter Sam bei 8 Jahren je Lebensjahr hat. Dann rechnest du auf 20 Jahre hoch und vergleichst.", "w": "Bei Proportionalität: 128 : 8 = 16 cm je Jahr. Mit 20 Jahren wären es 16 · 20 = 320 cm. Das sind 320 − 180 = 140 cm mehr als realistisch. Die Annahme stimmt nicht: Schon bei 12 Jahren wären es 192 cm statt 152 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14576}, {"l": "vervielfachen", "t": "tabelle", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Bei einem Bäcker kosten 4 Brezeln zusammen 5 €. Wie viele Brezeln bekommt man für 35 €?"}, "o": {"wert": 28, "einheit": "Brezeln"}, "h": "Wie oft passen 5 € in 35 €? So oft bekommst du 4 Brezeln.", "w": "5 € ergeben 4 Brezeln. 35 € sind 7 mal 5 €, also bekommt man 7 · 4 = 28 Brezeln.", "form": "anwenden", "zaehlt": "ja", "r": 14577}, {"l": "vervielfachen", "t": "tabelle", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Wanderer legt gleichmäßig 12 km in 3 Stunden zurück. Wie viele Minuten braucht er für 5 km?"}, "o": {"wert": 75, "einheit": "Minuten"}, "h": "Wie viele Kilometer schafft er in 1 Stunde? Wie viele Minuten braucht er dann für 1 km?", "w": "In 3 Stunden sind es 12 km, also 4 km in einer Stunde (60 Minuten). Für 1 km braucht er 60 : 4 = 15 Minuten, für 5 km also 5 · 15 = 75 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 14578}, {"l": "vervielfachen", "t": "tabelle", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rezept für 8 Personen braucht 600 g Mehl und 300 ml Milch. Zu Hause sind 1,5 kg Mehl und 600 ml Milch da. Für wie viele Personen reichen die Zutaten höchstens, wenn man nach dem Rezept kocht?"}, "o": {"wert": 16, "einheit": "Personen"}, "h": "Berechne getrennt, für wie viele Personen das Mehl und für wie viele die Milch reicht. Was begrenzt?", "w": "Mehl: 1 500 g : 600 g = 2,5 Rezepte, also 2,5 · 8 = 20 Personen. Milch: 600 ml : 300 ml = 2 Rezepte, also 2 · 8 = 16 Personen. Die Milch reicht nur für 16 Personen, sie begrenzt.", "form": "anwenden", "zaehlt": "ja", "r": 14579}, {"l": "pruefen", "t": "begriff", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim zahlt für 2 kg Birnen 5 €, für 3 kg Birnen 7,50 € und für 5 kg Birnen 12,50 €. Kim möchte wissen, was 8 kg Birnen kosten, wenn sich der Preis weiter in dieser Weise ändert. Wie viel Euro kosten 8 kg Birnen?"}, "o": {"wert": 20, "einheit": "€"}, "h": "Prüfe mit Preis : Gewicht in jeder Spalte, ob immer dieselbe Zahl herauskommt. Dann rechnest du weiter.", "w": "5 : 2 = 2,5; 7,5 : 3 = 2,5; 12,5 : 5 = 2,5. Immer 2,50 € je kg, die Tabelle ist proportional. 8 kg kosten 8 · 2,5 = 20 €. Probe: 3 kg + 5 kg: 7,50 + 12,50 = 20.", "form": "anwenden", "zaehlt": "ja", "r": 14580}, {"l": "pruefen", "t": "begriff", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Alle Paare einer Tabelle gehören zu einer proportionalen Zuordnung, nur ein Wert wurde falsch eingetragen: (4 | 18), (6 | 27), (10 | 46). Welche Zahl müsste statt 46 stehen?"}, "o": {"wert": 45}, "h": "Rechne in jeder Spalte zweite Zahl : erste Zahl. Welche Zahl kommt zweimal heraus?", "w": "18 : 4 = 4,5 und 27 : 6 = 4,5. Der Faktor ist 4,5. Bei 10 müsste 4,5 · 10 = 45 stehen, nicht 46. Probe: 46 : 10 = 4,6, das passt nicht zu 4,5.", "form": "anwenden", "zaehlt": "ja", "r": 14581}, {"l": "pruefen", "t": "begriff", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Eine Tabelle zeigt, wie viel Benzin ein Motorroller auf verschiedenen Strecken verbraucht: 40 km → 1 l; 60 km → 1,5 l; 100 km → 2,5 l. Wie viele Kilometer kommt der Roller mit 7,5 Litern, wenn der Verbrauch weiter in dieser Weise zunimmt?"}, "o": {"wert": 300, "einheit": "km"}, "h": "Prüfe, ob in jeder Spalte Liter : Kilometer dieselbe Zahl ergibt. Wie viele Kilometer fährt der Roller mit einem Liter? Dann rechnest du mit 7,5 Litern.", "w": "1 : 40 = 0,025; 1,5 : 60 = 0,025; 2,5 : 100 = 0,025. Es sind immer 0,025 l je km, die Zuordnung ist proportional. Mit 1 l kommt der Roller 40 km weit, mit 7,5 l also 7,5 · 40 = 300 km.", "form": "anwenden", "zaehlt": "ja", "r": 14582}]$auf$::jsonb),
    (305, 'terme.umformen_teil2', 789, 12, $auf$[{"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Tisch ist (x + 5) dm lang und (x + 3) dm breit. Seine Fläche in dm² ist ausmultipliziert x² + a · x + 15. Wie groß ist die Zahl a?"}, "o": {"wert": 8}, "h": "Multipliziere jedes Glied der ersten Klammer mit jedem Glied der zweiten. Welche Produkte enthalten x?", "w": "(x + 5)(x + 3) = x · x + x · 3 + 5 · x + 5 · 3 = x² + 3x + 5x + 15 = x² + 8x + 15. Also ist a = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14790}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Poster ist (x + 6) cm breit und (x − 2) cm hoch. Seine Fläche in cm² ist ausmultipliziert und zusammengefasst x² + p · x + q. Wie groß ist die Summe p + q?"}, "o": {"wert": -8}, "h": "Es entstehen vier Produkte. Achte beim Glied −2 auf das Vorzeichen. Fasse die Glieder mit x zusammen.", "w": "(x + 6)(x − 2) = x² − 2x + 6x − 12 = x² + 4x − 12. Also ist p = 4 und q = −12. Die Summe ist 4 + (−12) = −8.", "form": "anwenden", "zaehlt": "ja", "r": 14791}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine rechteckige Terrasse hat die Seitenlängen (x + a) m und (x + b) m, dabei sind a und b ganze Zahlen mit 0 < a < b. Ihre Fläche ist x² + 9x + 14 m². Wie lang ist die längere Seite der Terrasse, wenn x = 10 ist?"}, "o": {"wert": 17, "einheit": "m"}, "h": "Beim Ausmultiplizieren entsteht x² + (a + b) · x + a · b. Welche zwei ganzen Zahlen haben die Summe 9 und das Produkt 14?", "w": "Es muss a + b = 9 und a · b = 14 gelten. Das passt zu a = 2 und b = 7. Die Seiten sind (x + 2) und (x + 7). Für x = 10: 12 m und 17 m. Die längere Seite ist 17 m lang. Probe: (x + 2)(x + 7) = x² + 9x + 14.", "form": "anwenden", "zaehlt": "ja", "r": 14792}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Wand hat die Fläche 15x + 20 m². Sie ist ein Rechteck, und eine Seite ist 5 m lang. Wie lang ist die andere Seite, wenn x = 4 ist?"}, "o": {"wert": 16, "einheit": "m"}, "h": "Klammere den größten gemeinsamen Faktor aus. Er steht für die Seite, die du schon kennst.", "w": "15x + 20 = 5 · (3x + 4). Die eine Seite ist 5 m lang, also ist die andere Seite 3x + 4. Für x = 4: 3 · 4 + 4 = 16 m. Probe: 5 · 16 = 80 und 15 · 4 + 20 = 80.", "form": "anwenden", "zaehlt": "ja", "r": 14793}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Gewinn eines Marktstands ist G = 4x² + 28x Euro, wobei x die Zahl der verkauften Kisten ist. Klammert man den größten gemeinsamen Faktor aus, erhält man G = c · x · (x + d). Wie groß ist die Summe c + d?"}, "o": {"wert": 11}, "h": "Welche Zahl und welche Potenz von x stecken in beiden Gliedern? Was bleibt in der Klammer?", "w": "Der größte gemeinsame Faktor von 4x² und 28x ist 4x. 4x² : 4x = x und 28x : 4x = 7. Also G = 4x · (x + 7), das heißt c = 4 und d = 7. Die Summe ist 11. Probe: 4x · x + 4x · 7 = 4x² + 28x.", "form": "anwenden", "zaehlt": "ja", "r": 14794}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rechteck hat die Fläche 6x² + 9x (in cm²) und eine Seite der Länge 3x cm. Wie groß ist der Umfang des Rechtecks in cm, wenn x = 4 ist?"}, "o": {"wert": 46, "einheit": "cm"}, "h": "Die Fläche ist Länge mal Breite. Klammere 3x aus, dann erkennst du die andere Seite.", "w": "6x² + 9x = 3x · (2x + 3). Die eine Seite ist 3x, die andere 2x + 3. Für x = 4: 12 cm und 11 cm. Umfang = 2 · (12 + 11) = 46 cm. Probe: Fläche 12 · 11 = 132 = 6 · 16 + 9 · 4.", "form": "anwenden", "zaehlt": "ja", "r": 14795}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratischer Teppich hat die Seitenlänge (x + 3) m. Seine Fläche in m² ist ausmultipliziert x² + p · x + 9. Wie groß ist p?"}, "o": {"wert": 6}, "h": "Das Mittelglied bei (a + b)² ist 2 · a · b. Was ist hier a und was ist b?", "w": "(x + 3)² = x² + 2 · x · 3 + 3² = x² + 6x + 9. Also ist p = 6. Das Mittelglied darf man nie vergessen.", "form": "anwenden", "zaehlt": "ja", "r": 14796}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein rechteckiges Feld ist 52 m lang und 48 m breit. Wie groß ist seine Fläche in m²? Rechne geschickt mit (50 + 2) · (50 − 2)."}, "o": {"wert": 2496, "einheit": "m²"}, "h": "Die beiden Klammern unterscheiden sich nur im Vorzeichen. Welche binomische Formel passt?", "w": "(50 + 2)(50 − 2) = 50² − 2² = 2 500 − 4 = 2 496. Probe: 52 · 48 = 2 496.", "form": "anwenden", "zaehlt": "ja", "r": 14797}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein quadratisches Beet hat die Fläche 4x² + 20x + k (in m²) und die Seitenlänge 2x + m (in m). Dabei sind k und m feste Zahlen. Wie lang ist die Seite des Beets für x = 3?"}, "o": {"wert": 11, "einheit": "m"}, "h": "Vergleiche die Fläche mit (2x + m)². Welches Glied bei (2x + m)² enthält m und x?", "w": "(2x + m)² = 4x² + 4m · x + m². Der Vergleich mit 4x² + 20x + k gibt 4m = 20, also m = 5 (und k = 25). Die Seite ist 2x + 5. Für x = 3: 2 · 3 + 5 = 11 m. Probe: 11² = 121 = 4 · 9 + 20 · 3 + 25.", "form": "anwenden", "zaehlt": "ja", "r": 14798}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Foto hat die Seitenlänge x cm. Ein Rahmen ist ringsum 2 cm breit, der Rahmen allein hat die Fläche 48 cm². Die Außenseite des Rahmens ist x + 4 cm lang. Wie lang ist die Seite des Fotos in cm?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Die Rahmenfläche ist das äußere Quadrat minus das Foto. Stelle die Gleichung (x + 4)² − x² = 48 auf.", "w": "(x + 4)² − x² = 48 → x² + 8x + 16 − x² = 48 → 8x + 16 = 48 → 8x = 32 → x = 4. Das Foto ist 4 cm lang. Probe: 8² − 4² = 64 − 16 = 48.", "form": "anwenden", "zaehlt": "ja", "r": 14799}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein quadratisches Feld hat die Seitenlänge x + 5 m, ein zweites quadratisches Feld hat die Seitenlänge x − 3 m. Das erste Feld ist 96 m² größer als das zweite. Wie groß ist x?"}, "o": {"wert": 5, "einheit": "m"}, "h": "Multipliziere beide Klammern mit den binomischen Formeln aus. Was passiert mit x²?", "w": "(x + 5)² − (x − 3)² = 96 → x² + 10x + 25 − (x² − 6x + 9) = 96 → 16x + 16 = 96 → 16x = 80 → x = 5. Die Felder sind 10 m und 2 m lang. Probe: 100 − 4 = 96.", "form": "anwenden", "zaehlt": "ja", "r": 14800}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein quadratisches Grundstück hat die Seitenlänge x + 3 m. Ein rechteckiges Grundstück ist x m breit und x + 7 m lang. Beide Grundstücke sind gleich groß. Wie viele Quadratmeter hat jedes der beiden Grundstücke?"}, "o": {"wert": 144, "einheit": "m²"}, "h": "Stelle die Gleichung (x + 3)² = x · (x + 7) auf und löse sie. Danach berechnest du eine der beiden Flächen.", "w": "(x + 3)² = x · (x + 7) → x² + 6x + 9 = x² + 7x → 9 = x. Also x = 9. Quadrat: (9 + 3)² = 12 · 12 = 144 m². Probe mit dem Rechteck: 9 · 16 = 144 m².", "form": "anwenden", "zaehlt": "ja", "r": 14801}]$auf$::jsonb),
    (306, 'geometrie.konstruktion_teil2', 632, 6, $auf$[{"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Drachen aus Papier hat die Form eines Drachenvierecks ABCD. Die Symmetrieachse ist die Diagonale AC. Der Winkel bei A ist 70° und der Winkel bei C ist 50°. Wie groß ist der Winkel bei B?"}, "o": {"wert": 120, "einheit": "°"}, "h": "Welche beiden Winkel sind gleich groß? Alle vier Winkel zusammen ergeben 360°.", "w": "Die Winkel bei B und D sind gleich, weil die Figur symmetrisch zu AC ist. Alle vier Winkel ergeben 360°. Also ist 360° − 70° − 50° = 240° der Rest. Er verteilt sich auf zwei gleiche Winkel: 240° : 2 = 120°.", "form": "anwenden", "zaehlt": "ja", "r": 14633}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Fensterrahmen hat die Form eines Parallelogramms ABCD. Der Winkel bei A ist dreimal so groß wie der Winkel bei B. Wie groß ist der Winkel bei A?"}, "o": {"wert": 135, "einheit": "°"}, "h": "Welche Summe haben zwei benachbarte Winkel im Parallelogramm? Aus wie vielen gleichen Teilen besteht diese Summe?", "w": "Benachbarte Winkel im Parallelogramm ergeben zusammen 180°. Der Winkel bei A besteht aus 3 Teilen, der Winkel bei B aus 1 Teil, zusammen 4 Teile. Ein Teil ist 180° : 4 = 45°. Der Winkel bei A ist 3 · 45° = 135°. Probe: 135° + 45° = 180°.", "form": "anwenden", "zaehlt": "ja", "r": 14634}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einer Raute ABCD bildet die Diagonale AC mit der Seite AB einen Winkel von 28°. Sam baut die Raute aus vier gleich langen Holzstäben nach. Wie groß ist der Winkel bei B?"}, "o": {"wert": 124, "einheit": "°"}, "h": "Die Diagonale halbiert den Winkel bei A. Welcher Winkel ist ein Nachbar des Winkels bei A?", "w": "Die Diagonale AC halbiert den Winkel bei A, also ist der Winkel bei A gleich 2 · 28° = 56°. Benachbarte Winkel in der Raute ergeben zusammen 180°. Der Winkel bei B ist 180° − 56° = 124°.", "form": "anwenden", "zaehlt": "ja", "r": 14635}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Bastelprojekt sollst du ein Quadrat, eine Raute, ein Rechteck und ein Parallelogramm zeichnen. Jede Figur wird für sich und unabhängig von den anderen mit möglichst wenigen einzelnen Angaben (Seitenlängen oder Winkel) so festgelegt, dass sie bis auf Lage und Drehung eindeutig ist. Wie viele Angaben brauchst du für alle vier Figuren zusammen?"}, "o": {"wert": 8}, "h": "Wie viele Bestimmungsstücke braucht jede der vier Figuren einzeln?", "w": "Ein Quadrat braucht 1 Stück (die Seite). Eine Raute braucht 2 Stücke, ein Rechteck 2 Stücke, ein Parallelogramm 3 Stücke. Zusammen: 1 + 2 + 2 + 3 = 8 Angaben.", "form": "anwenden", "zaehlt": "ja", "r": 14636}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Noa konstruiert ein Drachenviereck ABCD mit der Symmetrieachse AC. Gezeichnet sind schon die Seite AB, der Winkel bei A (100°) und der Winkel bei B (70°). Nun trägt Noa den letzten Winkel bei C an. Wie groß muss dieser Winkel sein?"}, "o": {"wert": 120, "einheit": "°"}, "h": "Welche zwei Winkel sind gleich groß? Bedenke die Winkelsumme im Viereck.", "w": "Die Figur ist symmetrisch zu AC, also sind die Winkel bei B und D gleich: 70° und 70°. Alle vier Winkel ergeben 360°. Der Winkel bei C ist 360° − 100° − 70° − 70° = 120°.", "form": "anwenden", "zaehlt": "ja", "r": 14637}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Du konstruierst ein Schild in Form eines Parallelogramms ABCD: Du zeichnest die Seite AB und trägst bei A und bei B die Winkel an. Der stumpfe Winkel bei B ist um 36° kleiner als das Dreifache des spitzen Winkels bei A. Unter welchem Winkel (in Grad) trägst du bei B an?"}, "o": {"wert": 126, "einheit": "°"}, "h": "Benachbarte Winkel ergeben zusammen 180°. Schreibe den Winkel bei B mit dem Winkel bei A auf.", "w": "Es gilt α + β = 180° und β = 3α − 36°. Einsetzen: α + 3α − 36° = 180°, also 4α = 216° und α = 54°. Dann ist β = 180° − 54° = 126°. Probe: 3 · 54° − 36° = 126°.", "form": "anwenden", "zaehlt": "ja", "r": 14638}]$auf$::jsonb),
    (308, 'abbildungen.kongruenz_teil3', 751, 9, $auf$[{"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einem Spielfeld mit Koordinaten liegt die Mitte bei Z(2 | 3). Eine Spielfigur steht auf P(5 | 7). Eine zweite Figur steht genau gegenüber, sodass Z die Mitte der Strecke zwischen den beiden Figuren ist. Welche y-Koordinate hat die zweite Figur?"}, "o": {"wert": -1}, "h": "Von P(5 | 7) nach Z(2 | 3) ändert sich die y-Koordinate um einen bestimmten Betrag. Gehe denselben Weg von Z aus noch einmal.", "w": "In y-Richtung geht man von P nach Z um 7 − 3 = 4 nach unten. Von Z aus noch einmal 4 nach unten: 3 − 4 = −1. Oder: y′ = 2 · 3 − 7 = −1. Die zweite Figur hat die y-Koordinate −1.", "form": "anwenden", "zaehlt": "ja", "r": 14752}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Drohne fliegt in gerader Linie von R(−4 | 6) über eine Landeplatte bei S(2 | 3) hinweg und genau so weit dahinter weiter. S liegt also in der Mitte ihres Flugwegs. Wie groß ist die Summe der beiden Koordinaten ihres Zielpunkts?"}, "o": {"wert": 8}, "h": "Wie weit geht es von R nach S in x-Richtung und wie weit in y-Richtung? Gehe denselben Weg von S noch einmal.", "w": "Von R nach S: x ändert sich um 2 − (−4) = 6, y um 3 − 6 = −3. Von S noch einmal: x = 2 + 6 = 8, y = 3 − 3 = 0. Der Zielpunkt ist (8 | 0). Die Summe der Koordinaten ist 8 + 0 = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14753}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Der Punkt P(4 | −3) wird an einem Punkt Z gespiegelt. Der Bildpunkt P′ liegt auf der y-Achse und hat die y-Koordinate 11. Wie groß ist die Summe der beiden Koordinaten von Z?"}, "o": {"wert": 6}, "h": "Wo liegen Punkte auf der y-Achse? Z ist die Mitte der Strecke von P nach P′.", "w": "Ein Punkt auf der y-Achse hat die x-Koordinate 0, also ist P′(0 | 11). Z ist die Mitte von P und P′: x = (4 + 0) : 2 = 2 und y = (−3 + 11) : 2 = 4. Also Z(2 | 4) und die Summe ist 6. Probe: Von P nach Z geht es 2 nach links und 7 nach oben, von Z nach P′ noch einmal.", "form": "anwenden", "zaehlt": "ja", "r": 14754}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einem Spielbrett mit Koordinatensystem steht eine Figur auf P(4 | 1). Sie wird um den Ursprung O(0 | 0) um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus (x | y) der Punkt (−y | x). Welche x-Koordinate hat die Figur danach?"}, "o": {"wert": -1}, "h": "Setze x = 4 und y = 1 in die Regel (x | y) → (−y | x) ein. Welche Zahl steht an erster Stelle?", "w": "Aus (4 | 1) wird (−1 | 4). Die x-Koordinate ist −1 (das Gegenteil der alten y-Koordinate 1).", "form": "anwenden", "zaehlt": "ja", "r": 14755}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Ausleger eines Krans dreht sich um den Mast bei Z(3 | −2) um 90° gegen den Uhrzeigersinn. Seine Spitze steht zuerst bei P(7 | 1). Aus einem Vektor (a | b) wird bei dieser Drehung der Vektor (−b | a). Wie groß ist die Summe der beiden Koordinaten der Spitze nach der Drehung?"}, "o": {"wert": 2}, "h": "Rechne zuerst den Vektor von Z nach P. Drehe diesen Vektor. Trage ihn danach wieder bei Z an.", "w": "Vektor von Z nach P: (7 − 3 | 1 − (−2)) = (4 | 3). Gedreht: (−3 | 4). Von Z aus: (3 + (−3) | −2 + 4) = (0 | 2). Die Summe der Koordinaten ist 0 + 2 = 2.", "form": "anwenden", "zaehlt": "ja", "r": 14756}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Figur wurde um Z(2 | 1) um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus einem Vektor (a | b) der Vektor (−b | a). Nach der Drehung steht die Figur bei P′(−2 | 7). Wie groß ist die Summe der beiden Koordinaten des Punktes P, an dem sie vorher stand?"}, "o": {"wert": 13}, "h": "Rechne den Vektor von Z nach P′. Welcher Vektor (a | b) wird durch die Drehung zu diesem Vektor?", "w": "Vektor von Z nach P′: (−2 − 2 | 7 − 1) = (−4 | 6). Er ist das Bild von (a | b) mit −b = −4 und a = 6, also b = 4. Der ursprüngliche Vektor ist (6 | 4). Von Z aus: P = (2 + 6 | 1 + 4) = (8 | 5). Die Summe ist 13. Probe: (6 | 4) wird zu (−4 | 6).", "form": "anwenden", "zaehlt": "ja", "r": 14757}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Drohne fliegt auf einer Karte (x zeigt nach Osten, y nach Norden) den Vektor (5 | 2). Dann dreht sie sich um 90° nach rechts, also im Uhrzeigersinn, und fliegt gleich weit. Dabei wird aus (x | y) der Vektor (y | −x). Welche y-Koordinate hat der zweite Flugvektor?"}, "o": {"wert": -5}, "h": "Setze x = 5 und y = 2 in die Regel (x | y) → (y | −x) ein. Welche Zahl steht an zweiter Stelle?", "w": "Aus (5 | 2) wird (2 | −5). Die zweite Koordinate ist −x = −5.", "form": "anwenden", "zaehlt": "ja", "r": 14758}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Wanderer geht auf einer Karte von A(−2 | 3) nach B(4 | 5). Der Vektor AB wird um 90° gegen den Uhrzeigersinn gedreht (aus (x | y) wird (−y | x)) und bei B angesetzt. Er endet in C. Welche y-Koordinate hat C?"}, "o": {"wert": 11}, "h": "Berechne zuerst den Vektor AB. Drehe ihn, dann gehe vom Punkt B aus weiter.", "w": "AB = (4 − (−2) | 5 − 3) = (6 | 2). Gedreht: (−2 | 6). Von B(4 | 5) aus: C = (4 − 2 | 5 + 6) = (2 | 11). Die y-Koordinate ist 11.", "form": "anwenden", "zaehlt": "ja", "r": 14759}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Vektor v wird nacheinander um +90°, um 180° und um −90° gedreht. Das Ergebnis ist der Vektor (−3 | 7). Dabei gilt: +90°: (x | y) → (−y | x); −90°: (x | y) → (y | −x); 180°: (x | y) → (−x | −y). Wie groß ist die Summe der beiden Koordinaten von v?"}, "o": {"wert": -4}, "h": "Wie viel wird insgesamt gedreht? Fasse die drei Drehungen zu einer zusammen.", "w": "Insgesamt wird um 90° + 180° − 90° = 180° gedreht. Eine Drehung um 180° macht aus v = (x | y) den Vektor (−x | −y) = (−3 | 7). Also ist v = (3 | −7). Die Summe ist 3 + (−7) = −4.", "form": "anwenden", "zaehlt": "ja", "r": 14760}]$auf$::jsonb),
    (310, 'raum.schraegbilder_teil2', 582, 12, $auf$[{"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zimmer hat die Form eines Quaders. Die Ecke A liegt im Ursprung (0 | 0 | 0). Das Zimmer ist 6 m lang (x-Richtung), 3 m breit (y-Richtung) und 4 m hoch (z-Richtung). Die Ecke G liegt A genau gegenüber, an der Decke. Wie groß ist die Summe der drei Koordinaten von G?"}, "o": {"wert": 13}, "h": "Wie weit ist G von A entfernt, in x-, in y- und in z-Richtung?", "w": "G liegt 6 m in x-Richtung, 3 m in y-Richtung und 4 m in z-Richtung von A entfernt. Also G(6 | 3 | 4). Die Summe ist 6 + 3 + 4 = 13.", "form": "anwenden", "zaehlt": "ja", "r": 14583}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ABCDEFGH hat die Ecken A(1 | 2 | 0), B(7 | 2 | 0), D(1 | 5 | 0) und E(1 | 2 | 4). Seine Kanten verlaufen parallel zu den Achsen. M ist der Mittelpunkt des ganzen Quaders. Wie groß ist die Summe der drei Koordinaten von M? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 9.5}, "h": "Der Mittelpunkt liegt in jeder Richtung genau in der Mitte zwischen der kleinsten und der größten Koordinate. Welche Ecke liegt A gegenüber?", "w": "Die Ecke G liegt A gegenüber: G(7 | 5 | 4). M ist die Mitte von A und G: x = (1 + 7) : 2 = 4, y = (2 + 5) : 2 = 3,5, z = (0 + 4) : 2 = 2. Also M(4 | 3,5 | 2). Die Summe ist 4 + 3,5 + 2 = 9,5.", "form": "anwenden", "zaehlt": "ja", "r": 14584}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader steht auf dem Boden (der xy-Ebene) mit der Ecke A im Ursprung und ragt nach oben. Seine Kanten verlaufen parallel zu den Achsen. Die Ecke G, die A gegenüberliegt, hat die Koordinaten (8 | 6 | h). Das Volumen ist 240 Volumeneinheiten. Ein zweiter Quader steht auf demselben Bodenrechteck mit derselben Ecke A im Ursprung, ist aber doppelt so hoch. Wie groß ist die Summe der drei Koordinaten seiner Ecke G′, die A gegenüberliegt?"}, "o": {"wert": 24}, "h": "Berechne zuerst h aus dem Volumen. Die Koordinaten von G′ sind die Kantenlängen des zweiten Quaders.", "w": "Die Kanten sind 8, 6 und h lang. Das Volumen ist 8 · 6 · h = 240, also h = 5. Der zweite Quader ist 2 · 5 = 10 hoch, also G′(8 | 6 | 10). Die Summe ist 8 + 6 + 10 = 24.", "form": "anwenden", "zaehlt": "ja", "r": 14585}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Töpfer stellt sich vor, dass ein Rechteck mit den Seiten 4 cm und 9 cm um die 9-cm-Seite rotiert. Es entsteht ein Zylinder. Wie groß ist sein Volumen in cm³? Rechne mit π ≈ 3,14."}, "o": {"wert": 452.16, "einheit": "cm³"}, "h": "Welche Seite liegt auf der Drehachse? Die andere Seite wird zum Radius des Kreises.", "w": "Die 9-cm-Seite liegt auf der Achse und wird die Höhe, die 4-cm-Seite wird der Radius. V = π · r² · h ≈ 3,14 · 16 · 9 = 452,16 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14586}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rechteck mit den Seiten 5 cm und 8 cm dreht sich einmal um die 8-cm-Seite und einmal um die 5-cm-Seite. So entstehen zwei verschiedene Zylinder. Um wie viele Kubikzentimeter ist der größere Zylinder größer als der kleinere? Rechne mit π ≈ 3,14."}, "o": {"wert": 376.8, "einheit": "cm³"}, "h": "Berechne beide Volumina. Beachte, welche Seite jeweils zum Radius und welche zur Höhe wird.", "w": "Um die 8-cm-Seite: r = 5 cm, h = 8 cm, V = 3,14 · 25 · 8 = 628 cm³. Um die 5-cm-Seite: r = 8 cm, h = 5 cm, V = 3,14 · 64 · 5 = 1 004,8 cm³. Unterschied: 1 004,8 − 628 = 376,8 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14587}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Rechteck dreht sich um eine Seite, die 8 cm lang ist. Der entstehende Zylinder hat das Volumen 226,08 cm³. Rechne mit π ≈ 3,14. Wie breit ist das Rechteck in Zentimetern?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Die gesuchte Breite wird beim Drehen zum Radius. Stelle die Volumenformel nach r² um.", "w": "Die 8-cm-Seite wird die Höhe, die gesuchte Breite wird der Radius r. Aus 3,14 · r² · 8 = 226,08 folgt r² = 226,08 : 25,12 = 9. Also ist r = 3 cm. Probe: 3,14 · 9 · 8 = 226,08.", "form": "anwenden", "zaehlt": "ja", "r": 14588}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein massiver Holzkegel hat den Radius 3 cm und die Höhe 12 cm. Sam sägt ihn der Länge nach genau durch die Achse durch. Wie groß ist die Fläche der Schnittfläche in cm²?"}, "o": {"wert": 36, "einheit": "cm²"}, "h": "Der Axialschnitt eines Kegels ist ein Dreieck. Wie lang ist seine Grundseite, und wie hoch ist es?", "w": "Der Axialschnitt ist ein gleichschenkliges Dreieck. Die Grundseite ist der Durchmesser 2 · 3 = 6 cm, die Höhe ist 12 cm. A = 6 · 12 : 2 = 36 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14589}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Holzkugel wird genau durch ihren Mittelpunkt in zwei Hälften gesägt. Der Umfang der Schnittfläche ist 62,8 cm. Rechne mit π ≈ 3,14. Wie groß ist die Fläche der Schnittfläche in cm²?"}, "o": {"wert": 314, "einheit": "cm²"}, "h": "Die Schnittfläche ist ein Kreis mit dem Radius der Kugel. Berechne zuerst den Radius aus dem Umfang.", "w": "Der Schnitt ist ein Kreis mit dem Radius r der Kugel. Aus dem Umfang 2 · 3,14 · r = 62,8 folgt r = 62,8 : 6,28 = 10 cm. Die Fläche ist 3,14 · 10 · 10 = 314 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14590}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Der Axialschnitt eines Zylinders ist ein Rechteck mit dem Umfang 60 cm. Die Höhe des Zylinders ist doppelt so groß wie sein Durchmesser. Rechne mit π ≈ 3,14. Wie groß ist die Mantelfläche des Zylinders in cm²?"}, "o": {"wert": 628, "einheit": "cm²"}, "h": "Der Axialschnitt hat die Seiten d und 2d. Wie groß ist sein Umfang, wenn du ihn mit d aufschreibst? Wie berechnet man die Mantelfläche?", "w": "Der Axialschnitt hat die Seiten d und h = 2d. Umfang: 2 · (d + 2d) = 6d = 60, also d = 10 cm und h = 20 cm. Mantelfläche M = π · d · h = 3,14 · 10 · 20 = 628 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14591}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Bauteil aus Holz ist ein gerades Prisma, dessen Grundfläche ein regelmäßiges Neuneck ist. Ein zweites Bauteil ist eine gerade Pyramide über einem regelmäßigen Siebeneck. Um wie viele Symmetrieebenen hat das Prisma mehr als die Pyramide?"}, "o": {"wert": 3}, "h": "Wie viele Symmetrieebenen hat ein gerades Prisma über einem regelmäßigen n-Eck, wie viele eine gerade Pyramide über einem regelmäßigen n-Eck? Bilde dann den Unterschied.", "w": "Das gerade Prisma über dem Neuneck hat 9 Ebenen durch die Höhe und die Ebene in halber Höhe: 9 + 1 = 10 Symmetrieebenen. Die gerade Pyramide über dem Siebeneck hat nur die 7 Ebenen durch die Spitze, denn eine Ebene in halber Höhe gibt es bei einer Pyramide nicht. Unterschied: 10 − 7 = 3. (Sonderfälle wie ein Würfel kommen hier nicht vor.)", "form": "anwenden", "zaehlt": "ja", "r": 14592}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spielzeughändler hat drei Körper: einen Würfel, eine gerade Pyramide mit quadratischer Grundfläche und ein gerades Prisma, dessen Grundfläche ein gleichseitiges Dreieck ist. Wie viele Symmetrieebenen haben die drei Körper zusammen?"}, "o": {"wert": 17, "einheit": "Ebenen"}, "h": "Der Würfel hat 9 Ebenen. Für Pyramide und Prisma zählst du erst die Symmetrieachsen der Grundfläche. Beim Prisma kommt noch eine Ebene dazu.", "w": "Würfel: 9 Ebenen. Gerade Pyramide über dem Quadrat: 4 Ebenen (eine je Symmetrieachse des Quadrats). Gerades Prisma über dem gleichseitigen Dreieck: 3 Ebenen durch die Achsen des Dreiecks und 1 Ebene in halber Höhe, also 4. Zusammen 9 + 4 + 4 = 17.", "form": "anwenden", "zaehlt": "ja", "r": 14593}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein regelmäßiges Vieleck mit n Ecken. Das Prisma hat genau 7 Symmetrieebenen. Wie viele Kanten hat das Prisma?"}, "o": {"wert": 18, "einheit": "Kanten"}, "h": "Wie hängt die Zahl der Symmetrieebenen eines geraden Prismas mit der Eckenzahl n der Grundfläche zusammen? Wie viele Kanten hat ein Prisma mit n-Eck?", "w": "Die Symmetrieebenen des Prismas sind n Ebenen durch die Höhe (eine je Symmetrieachse des n-Ecks) und die Ebene in halber Höhe: zusammen n + 1. Eine Ausnahme ist der Würfel (n = 4, Höhe gleich Seitenlänge): Er hat 9 Symmetrieebenen, nicht 5. Hier sind es 7, also ist n = 6. Ein Prisma über einem Sechseck hat 6 Kanten unten, 6 oben und 6 senkrechte: 3 · 6 = 18 Kanten.", "form": "anwenden", "zaehlt": "ja", "r": 14594}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 213 then fehler := fehler || ('zusammen ' || gesamt || ' statt 213')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (10, 11, 31, 52, 59, 93, 94, 95, 112, 304, 305, 306, 308, 310) group by 1 order by 1;
