    ('R14-V021', 112, 14127, 'a71930d54013e5c7779df67e33024a45', 'zahl', 'fehler_ganz', null, $rbf${"wert": 8}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "16", "text": "Kims Ergebnis a⁴ mit a = 2 ausgerechnet", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "0.03125", "text": "beim Teilen durch a⁻⁴ die Hochzahl 4 statt −4 abgezogen: a⁻⁵", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "0.5", "text": "das Teilen durch (a⁻¹)⁴ vergessen: a⁻¹", "fehlbild": null, "regel": null}]$rbf$::jsonb),
