    ('R14-V044', 305, 14791, '9050b26fb887bc247450194585b8acc2', 'zahl', 'summe_mal_summe', null, $rbf${"wert": -8}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "20", "text": "das Minuszeichen bei der 2 übersehen: x² + 8x + 12", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "16", "text": "das Vorzeichen des Produkts 6 mal (−2) falsch: x² + 4x + 12", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "4", "text": "nur p angegeben", "fehlbild": null, "regel": null}]$rbf$::jsonb),
