    ('R14-V046', 305, 14793, 'f33efa83da8c96e76f34815bda5fed9b', 'zahl', 'ausklammern', null, $rbf${"wert": 16, "einheit": "m"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "80", "text": "die Fläche statt der Seitenlänge angegeben", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "32", "text": "nur das erste Glied durch 5 geteilt: 3x + 20", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "64", "text": "nur das zweite Glied durch 5 geteilt: 15x + 4", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V047', 305, 14794, '45779e4a2987e37c466ea8bf2a8ed2e4', 'zahl', 'ausklammern', null, $rbf${"wert": 11}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "28", "text": "c und d malgenommen statt addiert", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "7", "text": "nur d angegeben", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "8", "text": "den Faktor 4 vergessen, also c = 1", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V048', 305, 14795, '1a291b47f6f2798c62c89be725cb6abc', 'zahl', 'ausklammern', null, $rbf${"wert": 46, "einheit": "cm"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "23", "text": "den Umfang nicht verdoppelt: nur beide Seiten addiert", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "132", "text": "die Fläche statt des Umfangs angegeben", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "40", "text": "die 3 in der zweiten Seite vergessen (2x statt 2x + 3)", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V049', 305, 14796, '1c8e0c6a863c9048e841fc8f5ad16f8f', 'zahl', 'binomisch', null, $rbf${"wert": 6}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "3", "text": "nur die Zahl 3 als Mittelglied genommen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "0", "text": "das Mittelglied ganz vergessen: (x + 3)² = x² + 9", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "9", "text": "das Quadrat 3² als Mittelglied genommen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V050', 305, 14797, '4f76ca86b35f0354e0ac8e1e6d8cb7a8', 'zahl', 'binomisch', null, $rbf${"wert": 2496, "einheit": "m²"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "2500", "text": "nur 50² gerechnet, das Quadrat von 2 vergessen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "2504", "text": "2² addiert statt subtrahiert", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "2400", "text": "vom Quadrat 50² das Produkt aus 2 und 50 abgezogen statt 2²", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V051', 305, 14798, '2f77060f8ca4ffc0acfecbbce59f664c', 'zahl', 'binomisch', null, $rbf${"wert": 11, "einheit": "m"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "16", "text": "m = 10 aus 2m = 20 genommen: Mittelglied falsch gedeutet", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "121", "text": "die Fläche statt der Seitenlänge angegeben", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "9", "text": "m = 3 genommen: x selbst statt der Zahl m", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V052', 305, 14799, '8f3b674e6a6b2ae6d81066f5b53e1141', 'zahl', 'gleichungen_binomisch', null, $rbf${"wert": 4, "einheit": "cm"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "11", "text": "den Rahmen nur einmal gerechnet: (x + 2)² − x² = 48", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "6", "text": "48 durch 8 geteilt, ohne 16 abzuziehen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "8", "text": "die Außenseite des Rahmens statt des Fotos angegeben", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V053', 305, 14800, 'e4572728011eba8afb2f99200202a58d', 'zahl', 'gleichungen_binomisch', null, $rbf${"wert": 5, "einheit": "m"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "6", "text": "16 nicht abgezogen: 96 durch 16 geteilt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "8", "text": "das Mittelglied der zweiten Klammer vergessen: (x − 3)² = x² + 9", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "7", "text": "die 16 addiert statt abgezogen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R14-V054', 305, 14801, '8eddec3a608605b4ffe6d03de9f4d370', 'zahl', 'gleichungen_binomisch', null, $rbf${"wert": 144, "einheit": "m²"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "81", "text": "x = 9 als Seitenlänge des Quadrats genommen und quadriert", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "12", "text": "die Seitenlänge des Quadrats statt der Fläche angegeben", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "63", "text": "x mal 7 gerechnet", "fehlbild": null, "regel": null}]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      insert into schule.aufgabe_fehlbild (aufgabe_id, nr, art, luecke, wert, beschreibung, fehlbild, regel)
      values (a.id, (f->>'nr')::smallint, f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') on conflict do nothing;
      get diagnostics c = row_count; n_fb_neu := n_fb_neu + c;
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s steht schon anders da (oder gleicher Schlüssel unter anderer Nummer)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if coalesce(array_length(v_ids, 1), 0) <> 213
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 0
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 640 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 213)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
